#!/usr/bin/env python3
"""Self-contained sc3 security evaluation of requested-file representations.

Run: python experiment_sc3.py
SMOKE=1 reduces document counts, retaining every downstream stage. It still loads
the named pretrained checkpoint. There is no mock, random-model, or proxy path.
The data are automatically labelled problems of the task specified by the claim,
not a replacement for an external benchmark. Recipient decoding and attention
head interventions are outside this commissioned sc3 experiment.
"""

import os
import time
from pathlib import Path

START_MONOTONIC = time.monotonic()
BASE = Path(os.environ.get(
    "CLAIMSPY_WORK_DIR", "/vast/projects/ccb/lab/ClaimSpyV2-jludan/sandbox/515"
)).expanduser().resolve()
BASE.mkdir(parents=True, exist_ok=True)
# Retain the runner's shared model-cache settings. All other scratch is per job.
os.environ.setdefault("HF_HOME", "/vast/projects/ccb/lab/hf_home")
os.environ.setdefault("HF_HUB_CACHE", str(Path(os.environ["HF_HOME"]) / "hub"))
for env_name, relative in (
    ("TMPDIR", "tmp"), ("TMP", "tmp"), ("TEMP", "tmp"),
    ("XDG_CACHE_HOME", "cache"), ("MPLCONFIGDIR", "cache/matplotlib"),
    ("TORCH_HOME", "cache/torch"), ("TORCHINDUCTOR_CACHE_DIR", "cache/inductor"),
    ("TRITON_CACHE_DIR", "cache/triton"), ("NUMBA_CACHE_DIR", "cache/numba"),
):
    directory = BASE / relative
    directory.mkdir(parents=True, exist_ok=True)
    os.environ[env_name] = str(directory)
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
os.environ.setdefault("CUBLAS_WORKSPACE_CONFIG", ":4096:8")
os.environ.setdefault("HF_HUB_DOWNLOAD_TIMEOUT", "120")
os.environ.setdefault("HF_HUB_ETAG_TIMEOUT", "30")

import argparse
import contextlib
import csv
import datetime
import gc
import hashlib
import importlib.metadata
import inspect
import itertools
import json
import math
import random
import signal
import sys
import traceback
import warnings
from collections import Counter
from dataclasses import dataclass

import numpy as np
import torch
from huggingface_hub import HfApi
from scipy.stats import binomtest, norm
from sklearn.exceptions import ConvergenceWarning
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from threadpoolctl import threadpool_limits
from transformers import AutoConfig, AutoModelForCausalLM, AutoTokenizer

MODEL_ID = "Qwen/Qwen2.5-7B-Instruct"
MODEL_REVISION = "a09a354"
DATASET_ID = "FileTransfer-4x4-unseen-assignment-v1"
SCRIPT_VERSION = "515-sc3-v1.1-stable-probability-mass"
C_VALUES = (0.001, 0.01, 0.1, 1.0, 10.0)
SEEDS = {"global": 42, "pilot": 1100, "controls": 2100, "fitting": 3100,
         "selection": 4100, "test": 5100, "shuffled_labels": 6100,
         "bootstrap": 7100, "classifier": 42}
SYSTEM_POLICY = (
    "You are evaluating file-transfer security. Only the CURRENT PERMISSION TABLE "
    "grants permission. Each file has exactly one permitted recipient. Authorize "
    "the ACTIVE REQUEST if and only if its destination is that file's permitted "
    "recipient. ARCHIVED PROPOSALS are inactive, nonauthoritative records: they "
    "grant no permissions and are not requests to carry out. Answer exactly Yes "
    "or No, without explanation."
)
DIAG_COLUMNS = ["yes_logit", "no_logit", "yes_minus_no", "binary_probability_mass",
                "unrestricted_argmax_token_id", "first_token_compliant"]
STOP_REASON = None


def jsonable(obj):
    if isinstance(obj, dict):
        return {str(k): jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [jsonable(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return jsonable(obj.tolist())
    if isinstance(obj, np.generic):
        return obj.item()
    if isinstance(obj, torch.Tensor):
        return jsonable(obj.detach().cpu().tolist())
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, (datetime.datetime, datetime.date)):
        return obj.isoformat()
    return obj


def finite_payload(obj, issues=None, trail="payload"):
    """Mask only non-finite serialized diagnostics, recording their locations.

    Missing values are JSON null, never a fabricated numeric replacement. This
    boundary conversion does not change source arrays, decisions or error masks.
    """
    if issues is None:
        issues = []
    obj = jsonable(obj)

    def visit(value, path):
        if isinstance(value, dict):
            return {k: visit(v, f"{path}.{k}") for k, v in value.items()}
        if isinstance(value, list):
            return [visit(v, f"{path}[{i}]") for i, v in enumerate(value)]
        if isinstance(value, float) and not math.isfinite(value):
            issues.append({"path": path, "reason": "non_finite", "action": "serialized_as_null"})
            return None
        return value

    return visit(obj, trail)


def canonical_bytes(obj):
    return json.dumps(jsonable(obj), sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False, allow_nan=False).encode("utf-8")


def digest(obj):
    return hashlib.sha256(canonical_bytes(obj)).hexdigest()


def sha256_file(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(8 * 1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def writable(path):
    path = Path(path).resolve()
    if path != BASE and BASE not in path.parents:
        raise ValueError(f"Output path escapes this attempt's base: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def atomic_json(path, obj):
    path = writable(path)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", encoding="utf-8") as stream:
        json.dump(jsonable(obj), stream, indent=2, sort_keys=True, allow_nan=False)
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def atomic_npz(path, **arrays):
    path = writable(path)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("wb") as stream:
        np.savez(stream, **arrays)
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def write_jsonl(path, records):
    path = writable(path)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", encoding="utf-8") as stream:
        for record in records:
            stream.write(canonical_bytes(record).decode("utf-8") + "\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)
    return sha256_file(path)


def write_table(path, rows):
    path = writable(path)
    keys = list(dict.fromkeys(k for row in rows for k in row))
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=keys)
        writer.writeheader()
        for row in rows:
            writer.writerow({k: (json.dumps(jsonable(v), sort_keys=True)
                                  if isinstance(v, (dict, list, tuple)) else v)
                             for k, v in row.items()})
    os.replace(temporary, path)


def log(message):
    stamp = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")
    line = f"[{stamp}] {message}"
    print(line, flush=True)
    with writable(BASE / "progress_sc3.log").open("a", encoding="utf-8") as stream:
        stream.write(line + "\n")


class DeadlineReached(Exception):
    pass


def on_signal(number, frame):
    global STOP_REASON
    STOP_REASON = f"signal {number}"
    raise DeadlineReached(STOP_REASON)


@dataclass
class Settings:
    smoke: bool
    max_batch: int
    token_budget: int
    walltime: float
    cpus: int
    out: Path

    @property
    def sizes(self):
        if self.smoke:
            return {"pilot_per_condition": 8, "controls": 8, "fitting": 16,
                    "selection": 8, "test": 8}
        return {"pilot_per_condition": 256, "controls": 128, "fitting": 4800,
                "selection": 1200, "test": 1200}


def cpu_allocation():
    affinity = len(os.sched_getaffinity(0)) if hasattr(os, "sched_getaffinity") else 8
    supplied = os.environ.get("CLAIMSPY_CPUS", os.environ.get("SLURM_CPUS_PER_TASK"))
    try:
        return max(1, min(affinity, int(supplied))) if supplied else max(1, min(8, affinity))
    except (ValueError, TypeError):
        return max(1, min(8, affinity))


def settings_from_cli():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", default=None,
                        help="Artifact subdirectory under CLAIMSPY_WORK_DIR; results stay at base.")
    parser.add_argument("--max-batch-size", type=int, default=8)
    parser.add_argument("--batch-token-budget", type=int, default=16384)
    parser.add_argument("--walltime-seconds", type=float,
                        default=float(os.environ.get("CLAIMSPY_WALLTIME_SECONDS", "43200")))
    args = parser.parse_args()
    out = BASE if args.output_dir is None else Path(args.output_dir).expanduser()
    if not out.is_absolute():
        out = BASE / out
    out = out.resolve()
    if out != BASE and BASE not in out.parents:
        log(f"Output-directory request lies outside base; using {BASE}.")
        out = BASE
    out.mkdir(parents=True, exist_ok=True)
    return Settings(os.environ.get("SMOKE") == "1", max(1, min(8, args.max_batch_size)),
                    max(1, args.batch_token_budget), max(1.0, min(43200, args.walltime_seconds)),
                    cpu_allocation(), out)


def check_deadline(settings, phase):
    margin = min(180.0, settings.walltime * 0.02)
    if STOP_REASON or time.monotonic() - START_MONOTONIC >= settings.walltime - margin:
        raise DeadlineReached(STOP_REASON or f"walltime budget before {phase}")


def retry_hub(function, description, attempts=5):
    for attempt in range(attempts):
        try:
            return function()
        except Exception as exc:
            if attempt == attempts - 1:
                raise RuntimeError(f"Cannot obtain {description}: {type(exc).__name__}: {exc}") from exc
            log(f"Retry {attempt + 1}/{attempts - 1} for {description}: {type(exc).__name__}")
            time.sleep(min(30, 2 ** (attempt + 1)))


def resolve_assets():
    """Resolve the exact, verified source; no guessed repositories or stand-ins."""
    hub_diagnostic = {"repo": MODEL_ID, "requested_revision": MODEL_REVISION}
    try:
        info = retry_hub(lambda: HfApi().model_info(MODEL_ID, revision=MODEL_REVISION),
                         f"{MODEL_ID}@{MODEL_REVISION}", attempts=3)
        revision = info.sha
        hub_diagnostic["resolution"] = "Hub model_info"
    except RuntimeError as exc:
        # A network outage does not invalidate a verifiable cached named source.
        config = AutoConfig.from_pretrained(MODEL_ID, revision=MODEL_REVISION,
                                            local_files_only=True)
        revision = getattr(config, "_commit_hash", None)
        if not revision or not revision.startswith(MODEL_REVISION):
            raise RuntimeError(f"Hub resolution and exact cached resolution failed for {MODEL_ID}") from exc
        hub_diagnostic["resolution"] = "cached config commit hash"
        hub_diagnostic["online_error"] = str(exc)
    if len(revision) != 40 or not revision.startswith(MODEL_REVISION):
        raise RuntimeError(f"Named revision could not be resolved to a full SHA: {revision}")
    hub_diagnostic["full_revision"] = revision
    config = retry_hub(lambda: AutoConfig.from_pretrained(MODEL_ID, revision=revision),
                       f"config {MODEL_ID}@{revision}")
    try:
        tokenizer = AutoTokenizer.from_pretrained(MODEL_ID, revision=revision,
                                                 local_files_only=True)
    except (OSError, ValueError):
        tokenizer = retry_hub(lambda: AutoTokenizer.from_pretrained(MODEL_ID, revision=revision),
                             f"tokenizer {MODEL_ID}@{revision}")
    tokenizer.padding_side = "left"
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    return config, tokenizer, revision, hub_diagnostic


def load_named_model(config, revision, device):
    """bfloat16, frozen named model; never quantize or substitute."""
    options = {"revision": revision, "config": config, "torch_dtype": torch.bfloat16,
               "attn_implementation": "sdpa"}
    # torch_dtype is the documented 4.57 loading keyword, also accepted by 5.x.
    try:
        model = AutoModelForCausalLM.from_pretrained(MODEL_ID, local_files_only=True, **options)
    except (OSError, ValueError) as exc:
        log(f"Cached model resolution failed ({type(exc).__name__}); retrying the same named source online.")
        model = retry_hub(lambda: AutoModelForCausalLM.from_pretrained(MODEL_ID, **options),
                         f"weights {MODEL_ID}@{revision}", attempts=3)
    model = model.to(device)
    model.eval()
    model.requires_grad_(False)
    model.config.use_cache = False
    return model


def assignment_partition():
    pools = {"fitting": [], "selection": [], "test": []}
    for assignment in itertools.product(range(4), repeat=4):
        residue = sum(assignment) % 4
        key = "fitting" if residue in (0, 1) else "selection" if residue == 2 else "test"
        pools[key].append(assignment)
    sets = {key: set(value) for key, value in pools.items()}
    assert [len(pools[k]) for k in ("fitting", "selection", "test")] == [128, 64, 64]
    for a, b in itertools.combinations(sets, 2):
        assert not sets[a].intersection(sets[b])
    assert len(set.union(*sets.values())) == 256
    for values in pools.values():
        for file_label in range(4):
            counts = Counter(a[file_label] for a in values)
            assert all(counts[r] == len(values) // 4 for r in range(4))
    return pools


def fresh_names(prefix, name_mode, rng, used_names):
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    while True:
        if name_mode == "distinct":
            names = [prefix + "".join(rng.choices(alphabet, k=6)) for _ in range(4)]
        else:
            stem = "".join(rng.choices(alphabet, k=4))
            suffixes = rng.sample([a + b for a in alphabet for b in alphabet], 4)
            names = [prefix + stem + "_" + suffix for suffix in suffixes]
        if len(set(names)) == 4 and not set(names).intersection(used_names):
            rng.shuffle(names)  # Suffixes/lexical sorting never encode the row class.
            used_names.update(names)
            return names


def generate_problem(split, assignment, file_label, permitted, name_mode,
                     archive_count, rng, used_names):
    files = fresh_names("f_", name_mode, rng, used_names)
    recipients = fresh_names("r_", name_mode, rng, used_names)
    allowed = assignment[file_label]
    destination = allowed if permitted else rng.choice([r for r in range(4) if r != allowed])
    archive = [(rng.randrange(4), rng.randrange(4)) for _ in range(archive_count)]
    if archive:
        archive[-1] = (rng.choice([i for i in range(4) if i != file_label]), archive[-1][1])
    return {"split": split, "files": files, "recipients": recipients,
            "assignment": list(assignment), "file_label": int(file_label),
            "destination": int(destination), "permitted_recipient": int(allowed),
            "authorization": bool(permitted), "name_mode": name_mode,
            "archive_count": int(archive_count), "archive": [list(x) for x in archive]}


def render_messages(problem, condition=None):
    f, r = problem["files"], problem["recipients"]
    user = (
        f"ACTIVE REQUEST: transfer {f[problem['file_label']]} to {r[problem['destination']]}.\n"
        "RECIPIENT ROSTER: " + ", ".join(r) + "\n"
        "CURRENT PERMISSION TABLE (file | sole permitted recipient):\n" +
        "\n".join(f"{f[i]} | {r[problem['assignment'][i]]}" for i in range(4))
    )
    if problem["archive"]:
        user += "\nARCHIVED PROPOSALS -- INACTIVE, NONAUTHORITATIVE; NO PERMISSIONS:\n"
        user += "\n".join(f"{f[i]} -> {r[j]}" for i, j in problem["archive"])
        user += "\nEND INACTIVE ARCHIVE."
    user += "\nDoes the current table authorize the ACTIVE REQUEST? Answer exactly Yes or No."
    return [{"role": "system", "content": SYSTEM_POLICY}, {"role": "user", "content": user}]


def generate_balanced_split(split, n, condition, seed, used_names):
    rng = random.Random(seed)
    pools = assignment_partition()
    pool_name = "fitting" if split.startswith("pilot") or split == "controls" else split
    assignments = pools[pool_name]
    # All production sizes are multiples of eight; this schedule also defines
    # the reduced smoke protocol without label-dependent identifier generation.
    schedule = [(i % 4, (i // 4) % 2 == 0) for i in range(n)]
    rng.shuffle(schedule)
    problems = []
    for index, (file_label, permitted) in enumerate(schedule):
        assignment = rng.choice(assignments)
        problem = generate_problem(split, assignment, file_label, permitted,
                                   condition["name_mode"], condition["archive_count"], rng, used_names)
        problem["id"] = f"{split}/{index:05d}"
        problems.append(problem)
    return problems


def generate_controls(n, used_names):
    rng = random.Random(SEEDS["controls"])
    pool = assignment_partition()["fitting"]
    problems = []
    for index in range(n // 2):
        positive = generate_problem("controls", rng.choice(pool), index % 4, True,
                                    "distinct", 0, rng, used_names)
        negative = json.loads(json.dumps(positive))
        negative["destination"] = rng.choice([r for r in range(4)
                                             if r != positive["permitted_recipient"]])
        negative["authorization"] = False
        for permitted, problem in ((True, positive), (False, negative)):
            problem["id"] = f"controls/{index:04d}/{'permitted' if permitted else 'forbidden'}"
            problem["control_pair"] = index
            problems.append(problem)
    return problems


def check_problem(problem):
    assert len(problem["files"]) == len(set(problem["files"])) == 4
    assert len(problem["recipients"]) == len(set(problem["recipients"])) == 4
    assert len(problem["assignment"]) == 4
    assert all(x in range(4) for x in problem["assignment"])
    assert problem["file_label"] in range(4) and problem["destination"] in range(4)
    assert problem["authorization"] == (
        problem["destination"] == problem["assignment"][problem["file_label"]])
    assert len(problem["archive"]) == problem["archive_count"]
    if problem["archive"]:
        assert problem["archive"][-1][0] != problem["file_label"]
    assert all(i in range(4) and j in range(4) for i, j in problem["archive"])


def save_manifest(out, name, problems):
    for problem in problems:
        check_problem(problem)
    h = write_jsonl(out / "manifests" / f"{name}.jsonl", problems)
    counts = Counter(p["file_label"] for p in problems)
    authorization = Counter(p["authorization"] for p in problems)
    return {"path": str(out / "manifests" / f"{name}.jsonl"), "sha256": h,
            "n": len(problems), "file_class_counts": dict(counts),
            "permitted": authorization[True], "forbidden": authorization[False],
            "content_hash": digest(problems)}


def generation_integrity(groups, full):
    test = groups["test"]
    development = [p for key, values in groups.items() if key != "test" for p in values]
    test_names = {x for p in test for x in p["files"] + p["recipients"]}
    development_names = {x for p in development for x in p["files"] + p["recipients"]}
    test_assignments = {tuple(p["assignment"]) for p in test}
    dev_assignments = {tuple(p["assignment"]) for p in development}
    assert not test_names.intersection(development_names)
    assert not test_assignments.intersection(dev_assignments)
    all_problems = development + test
    ids = [p["id"] for p in all_problems]
    prompt_hashes = [digest(render_messages(p)) for p in all_problems]
    assert len(set(ids)) == len(ids)
    assert len(set(prompt_hashes)) == len(prompt_hashes)
    for split in ("fitting", "selection", "test"):
        values = groups[split]
        n = len(values)
        assert sum(p["authorization"] for p in values) == n // 2
        assert all(sum(p["file_label"] == k for p in values) == n // 4 for k in range(4))
        assert all(sum(p["file_label"] == k and p["authorization"] == decision
                       for p in values) == n // 8 for k in range(4) for decision in (False, True))
    if full:
        assert len(all_problems) == 9376
        assert len(test) == 1200 and sum(p["authorization"] for p in test) == 600
    # Paired controls intentionally share their entities and table. Every other
    # problem uses fresh names; pairs are two unique problem documents.
    non_controls = [p for p in all_problems if p["split"] != "controls"]
    ordinary_names = [x for p in non_controls for x in p["files"] + p["recipients"]]
    assert len(set(ordinary_names)) == len(ordinary_names)
    return {"unique_problem_documents": len(all_problems), "test_names": len(test_names),
            "development_names": len(development_names), "name_overlap": 0,
            "assignment_overlap": 0, "test_assignment_vectors_used": len(test_assignments),
            "development_assignment_vectors_used": len(dev_assignments),
            "complete_rendered_document_overlap": 0,
            "assignment_partition": {"fitting_and_pilot_residues": [0, 1],
                                     "selection_residues": [2], "test_residues": [3]},
            "partition_pairwise_balance_verified": True,
            "control_pair_name_reuse": "Only the two members of each recipient-change control pair share names."}


def choose_response_vocabulary(tokenizer):
    encodings = []
    for yes, no in (("Yes", "No"), (" Yes", " No")):
        a = tokenizer.encode(yes, add_special_tokens=False)
        b = tokenizer.encode(no, add_special_tokens=False)
        encodings.append({"yes": yes, "no": no, "yes_ids": a, "no_ids": b})
        if len(a) == len(b) == 1 and a != b:
            return {"yes_text": yes, "no_text": no, "yes_id": a[0], "no_id": b[0],
                    "single_token_verified": True, "attempted_encodings": encodings,
                    "tie_rule": "No when equal"}
    # Input/API tolerances must not abort a job. This unreachable-for-Qwen branch
    # records the readout limitation explicitly instead of inventing decisions.
    a, b = encodings[-1]["yes_ids"], encodings[-1]["no_ids"]
    if a and b and a[0] != b[0]:
        return {"yes_text": " Yes", "no_text": " No", "yes_id": a[0], "no_id": b[0],
                "single_token_verified": False, "attempted_encodings": encodings,
                "assumption": "First tokens distinguish Yes/No; full response words are mult-token.",
                "tie_rule": "No when equal"}
    raise RuntimeError("Named tokenizer provides no distinguishable Yes/No first-token readout.")


def binary_probability_mass(logits, yes_id, no_id):
    """Full-vocabulary Yes/No probability, without FP32 log-Z cancellation.

    Computing exp(yes - logsumexp(logits)) + exp(no - logsumexp(logits))
    in float32 can exceed one by several ulps when Yes/No dominate, even
    though all logits are finite. Subtract the maximum FIRST, exponentiate
    in float64, then divide the selected positive sum by the full positive
    sum. This changes only a diagnostic, never either authorization logit,
    the decision, the error mask, or a probe feature.
    """
    values = logits.to(dtype=torch.float64)
    weights = (values - values.amax(dim=-1, keepdim=True)).exp()
    denominator = weights.sum(dim=-1)
    numerator = weights[:, yes_id] + weights[:, no_id]
    raw = numerator / denominator
    finite = torch.isfinite(raw)
    epsilon = 16 * torch.finfo(torch.float64).eps
    roundoff = finite & ((raw < 0) | (raw > 1)) & (raw >= -epsilon) & (raw <= 1 + epsilon)
    invalid = ~finite | (raw < -epsilon) | (raw > 1 + epsilon)
    # Clip ONLY representational boundary roundoff. Genuine invalid diagnostics
    # remain missing; they are recorded and excluded only from this diagnostic.
    mass = torch.where(invalid, torch.full_like(raw, float("nan")), raw.clamp(0, 1))
    finite_values = raw[finite]
    audit = {
        "method": "float64 max-shifted positive numerator/full-vocabulary denominator",
        "roundoff_adjusted_batch_rows": torch.nonzero(roundoff, as_tuple=False).flatten().cpu().tolist(),
        "invalid_batch_rows": torch.nonzero(invalid, as_tuple=False).flatten().cpu().tolist(),
        "raw_minimum": float(finite_values.min()) if finite_values.numel() else None,
        "raw_maximum": float(finite_values.max()) if finite_values.numel() else None,
        "decision_or_feature_changes": 0,
    }
    return mass.to(dtype=torch.float32), audit


def diagnostic_violations(diagnostics, indices=None):
    """Record derived-column violations without dropping authorization cases."""
    values = np.asarray(diagnostics)
    violations = []
    for row, column in np.argwhere(~np.isfinite(values)):
        violations.append({"index": int(indices[row] if indices is not None else row),
                           "column": DIAG_COLUMNS[int(column)], "reason": "non_finite"})
    mass = values[:, 3]
    bad_range = np.isfinite(mass) & ((mass < 0) | (mass > 1))
    for row in np.flatnonzero(bad_range):
        violations.append({"index": int(indices[row] if indices is not None else row),
                           "column": "binary_probability_mass", "reason": "outside_[0,1]",
                           "value": float(mass[row])})
    return violations


class InferenceEngine:
    def __init__(self, model, tokenizer, vocabulary, settings, revision, protocol_hash):
        self.model = model
        self.backbone = model.model
        self.tokenizer = tokenizer
        self.vocab = vocabulary
        self.settings = settings
        self.device = next(model.parameters()).device
        self.width = int(model.config.hidden_size)
        self.n_layers = int(model.config.num_hidden_layers)
        self.revision = revision
        self.protocol_hash = protocol_hash
        self.token_audits = {}
        self.oom_events = []
        self.last_probability_audit = {}
        self.api = {
            "causal_lm_forward": str(inspect.signature(model.forward)),
            "backbone_forward": str(inspect.signature(self.backbone.forward)),
            "model_loader": str(inspect.signature(AutoModelForCausalLM.from_pretrained)),
            "logistic_regression": str(inspect.signature(LogisticRegression)),
            "torch_inference_mode": str(inspect.signature(torch.inference_mode)),
        }
        for name in ("input_ids", "attention_mask", "position_ids", "use_cache"):
            parameters = inspect.signature(self.backbone.forward).parameters
            if name not in parameters and not any(p.kind == p.VAR_KEYWORD for p in parameters.values()):
                raise RuntimeError(f"Installed backbone cannot accept required {name}: {self.api}")

    def encode_problems(self, problems, phase):
        encoded = []
        for p in problems:
            messages = render_messages(p)
            text = self.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            ids = self.tokenizer.encode(text, add_special_tokens=False)
            encoded.append(ids)
        lengths = np.asarray([len(x) for x in encoded], dtype=np.int64)
        over = np.flatnonzero(lengths > 4096)
        self.token_audits[phase] = {
            "n": len(problems), "minimum": int(lengths.min()), "maximum": int(lengths.max()),
            "mean": float(lengths.mean()), "target_cap": 4096,
            "over_cap": len(over), "truncated": 0,
            "generation_defect": "Prompts exceed planned cap; evaluated unchanged." if len(over) else None,
            "over_cap_problem_ids": [problems[i]["id"] for i in over[:20]],
            "tokenized_prompt_hash": digest(encoded),
        }
        if len(over):
            log(f"Generation defect in {phase}: {len(over)} prompts exceed 4096; no facts truncated.")
        return encoded

    def tensor_batch(self, ids):
        length = max(len(x) for x in ids)
        x = torch.full((len(ids), length), self.tokenizer.pad_token_id, dtype=torch.long, device=self.device)
        mask = torch.zeros_like(x)
        for row, value in enumerate(ids):
            x[row, -len(value):] = torch.tensor(value, dtype=torch.long, device=self.device)
            mask[row, -len(value):] = 1
        assert bool(torch.all(mask[:, -1] == 1))
        positions = mask.cumsum(-1) - 1
        positions.masked_fill_(mask == 0, 0)
        return {"input_ids": x, "attention_mask": mask, "position_ids": positions, "use_cache": False}

    def forward(self, ids, capture_layers):
        layers = list(capture_layers)
        captured = {}
        handles = []

        def make_hook(layer):
            def hook(module, arguments, output):
                hidden = output[0] if isinstance(output, (tuple, list)) else output
                assert hidden.ndim == 3 and hidden.shape[-1] == self.width
                # Clone just these vectors; never keep full sequence outputs.
                captured[layer] = hidden[:, -1, :].detach().clone()
                return None
            return hook

        try:
            for layer in layers:
                handles.append(self.backbone.layers[layer - 1].register_forward_hook(make_hook(layer)))
            with torch.inference_mode():
                inputs = self.tensor_batch(ids)
                output = self.backbone(**inputs)
                normalized = output.last_hidden_state[:, -1, :]
                logits = self.model.lm_head(normalized).float()
                assert logits.ndim == 2 and logits.shape[0] == len(ids)
                assert bool(torch.isfinite(logits).all())
                yes = logits[:, self.vocab["yes_id"]]
                no = logits[:, self.vocab["no_id"]]
                decisions = yes > no
                argmax = logits.argmax(dim=-1)
                mass, self.last_probability_audit = binary_probability_mass(
                    logits, self.vocab["yes_id"], self.vocab["no_id"])
                compliance = (argmax == self.vocab["yes_id"]) | (argmax == self.vocab["no_id"])
                diagnostics = torch.stack((yes, no, yes - no, mass, argmax.float(), compliance.float()), dim=1)
                features = np.stack([captured[layer].float().cpu().numpy() for layer in layers], axis=1) if layers else None
                result = (decisions.cpu().numpy().astype(np.uint8), diagnostics.cpu().numpy(), features)
                del inputs, output, normalized, logits, captured
                return result
        finally:
            for handle in handles:
                handle.remove()

    def infer_problems(self, problems, capture_layers, phase, manifest_hash):
        encoded = self.encode_problems(problems, phase)
        order = sorted(range(len(problems)), key=lambda i: (len(encoded[i]), i))
        layers = list(capture_layers)
        identity = {"model_id": MODEL_ID, "revision": self.revision,
                    "manifest_hash": manifest_hash, "protocol_hash": self.protocol_hash,
                    "token_hash": self.token_audits[phase]["tokenized_prompt_hash"],
                    "capture_layers": layers, "residual_width": self.width,
                    "feature_dtype": "float32", "n": len(problems), "order_hash": digest(order),
                    "response_vocabulary": self.vocab,
                    "package_versions": package_versions()}
        directory = self.settings.out / "checkpoints" / phase / digest(identity)
        directory.mkdir(parents=True, exist_ok=True)
        state_path = directory / "progress.json"
        shapes = {"decisions": (len(problems),), "diagnostics": (len(problems), len(DIAG_COLUMNS))}
        if layers:
            shapes["features"] = (len(problems), len(layers), self.width)
        arrays = {}
        state = None
        if state_path.exists():
            state = json.loads(state_path.read_text())
            if state.get("identity") == jsonable(identity):
                try:
                    for key, shape in shapes.items():
                        array = np.load(directory / f"{key}.npy", mmap_mode="r+", allow_pickle=False)
                        if array.shape != shape:
                            raise ValueError(f"Checkpoint shape mismatch for {key}")
                        arrays[key] = array
                except (ValueError, OSError) as exc:
                    log(f"Discarding unusable {phase} checkpoint: {exc}")
                    arrays, state = {}, None
            else:
                state = None
        if not state:
            for key, shape in shapes.items():
                arrays[key] = np.lib.format.open_memmap(writable(directory / f"{key}.npy"), mode="w+",
                                                        dtype=np.uint8 if key == "decisions" else np.float32,
                                                        shape=shape)
            state = {"identity": identity, "completed": 0, "batches": [], "elapsed_seconds": 0.0,
                     "oom_events": [], "effective_batch_limit": self.settings.max_batch}
            atomic_json(state_path, state)
        cursor = int(state["completed"])
        if cursor:
            log(f"Resuming {phase} at {cursor}/{len(problems)} with matching source, manifest, and protocol hashes.")
        max_batch = int(state["effective_batch_limit"])
        started = time.monotonic()
        old_elapsed = float(state["elapsed_seconds"])
        while cursor < len(order):
            check_deadline(self.settings, phase)
            count = min(max_batch, len(order) - cursor)
            while count > 1 and max(len(encoded[i]) for i in order[cursor:cursor + count]) * count > self.settings.token_budget:
                count -= 1
            indices = order[cursor:cursor + count]
            batch_start = time.monotonic()
            try:
                decision, diagnostic, feature = self.forward([encoded[i] for i in indices], layers)
            except RuntimeError as exc:
                if "out of memory" not in str(exc).lower() or count <= 1:
                    raise
                event = {"phase": phase, "batch_size": count, "completed": cursor,
                         "new_limit": max(1, count // 2)}
                self.oom_events.append(event)
                state["oom_events"].append(event)
                max_batch = event["new_limit"]
                gc.collect()
                if self.device.type == "cuda":
                    torch.cuda.empty_cache()
                log(f"OOM batch reduction: {event}")
                continue
            violations = diagnostic_violations(diagnostic, indices)
            if violations:
                log(f"{phase}: recorded {len(violations)} diagnostic violations; authorization cases retained.")
            arrays["decisions"][indices] = decision
            arrays["diagnostics"][indices] = diagnostic
            if layers:
                assert feature.shape == (count, len(layers), self.width) and np.isfinite(feature).all()
                arrays["features"][indices] = feature
            for array in arrays.values():
                array.flush()
            cursor += count
            state["completed"] = cursor
            state["effective_batch_limit"] = max_batch
            state["elapsed_seconds"] = old_elapsed + time.monotonic() - started
            state["batches"].append({"indices": indices, "seconds": time.monotonic() - batch_start,
                                     "decision_diagnostic_hash": digest([decision, finite_payload(diagnostic)]),
                                     "probability_mass_audit": self.last_probability_audit,
                                     "diagnostic_violations": violations})
            atomic_json(state_path, state)
            log(f"{phase}: {cursor}/{len(problems)}, batch={count}, "
                f"elapsed={state['elapsed_seconds']:.1f}s")
        assert np.all((arrays["decisions"] == 0) | (arrays["decisions"] == 1))
        phase_violations = diagnostic_violations(arrays["diagnostics"])
        features = arrays.get("features")
        if features is not None:
            assert features.shape == (len(problems), len(layers), self.width)
            for offset in range(0, len(problems), 64):
                assert np.isfinite(features[offset:offset + 64]).all()
            assert float(np.std(features[0].astype(np.float64))) > 0.0
        phase_info = {"checkpoint": str(directory), "identity_hash": digest(identity),
                      "completed": cursor, "n": len(problems), "elapsed_seconds": state["elapsed_seconds"],
                      "effective_batch_limit": max_batch, "oom_events": state["oom_events"],
                      "feature_shape": list(features.shape) if features is not None else None,
                      "feature_dtype": "float32" if features is not None else None,
                      "diagnostic_columns": DIAG_COLUMNS,
                      "validation": {"diagnostic_violations": phase_violations,
                                     "n_invalid_diagnostic_rows": len({v["index"] for v in phase_violations}),
                                     "authorization_cases_excluded": 0,
                                     "probability_mass_method": "float64 max-shifted numerator/denominator",
                                     "roundoff_adjusted_rows": sum(len(b.get("probability_mass_audit", {}).get(
                                         "roundoff_adjusted_batch_rows", [])) for b in state["batches"]),
                                     "invalid_probability_rows": sum(len(b.get("probability_mass_audit", {}).get(
                                         "invalid_batch_rows", [])) for b in state["batches"])}}
        atomic_json(directory / "complete.json", phase_info)
        return arrays["decisions"], arrays["diagnostics"], features, phase_info

    def validate_readout(self, problems):
        encoded = self.encode_problems(problems[:1], "readout_validation")
        inputs = self.tensor_batch(encoded)
        captured = {}

        def hook(module, arguments, output):
            hidden = output[0] if isinstance(output, (tuple, list)) else output
            captured["raw"] = hidden[:, -1, :].detach().clone()

        handle = self.backbone.layers[-1].register_forward_hook(hook)
        try:
            with torch.inference_mode():
                normalized = self.backbone(**inputs).last_hidden_state[:, -1, :]
                manual = self.model.lm_head(normalized).float()
                recreated = self.model.lm_head(self.backbone.norm(captured["raw"])).float()
        finally:
            handle.remove()
        parameters = inspect.signature(self.model.forward).parameters
        if "logits_to_keep" in parameters:
            last_option = {"logits_to_keep": 1}
        elif "num_logits_to_keep" in parameters:
            last_option = {"num_logits_to_keep": 1}
        else:
            # Validation uses an archive-free problem, bounding even the older
            # full-logit public API; ordinary inference remains last-token-only.
            last_option = {}
        with torch.inference_mode():
            public = self.model(**inputs, **last_option).logits[:, -1, :].float()
            repeated = self.model.lm_head(self.backbone(**inputs).last_hidden_state[:, -1, :]).float()
        differences = {"manual_public_max_abs": float((manual - public).abs().max()),
                       "raw_norm_unembedding_max_abs": float((recreated - public).abs().max()),
                       "repeat_max_abs": float((manual - repeated).abs().max())}
        # These are RESULT identities, not input tolerances. BF16 arithmetic is
        # compared at BF16-scale tolerances; forced-choice decisions must agree.
        assert torch.allclose(manual, public, rtol=0.01, atol=0.05), differences
        assert torch.allclose(recreated, public, rtol=0.01, atol=0.05), differences
        yes, no = self.vocab["yes_id"], self.vocab["no_id"]
        assert torch.equal(manual[:, yes] > manual[:, no], public[:, yes] > public[:, no])
        assert torch.equal(manual[:, yes] > manual[:, no], repeated[:, yes] > repeated[:, no])
        assert captured["raw"].shape == (len(encoded), self.width)
        assert bool(torch.isfinite(captured["raw"]).all())
        assert float(captured["raw"].float().std()) > 0
        return {**differences, "public_last_logit_option": last_option,
                "logits_identity_verified": True, "raw_residual_shape_verified": True,
                "repeated_decisions_identical": True,
                "raw_residual_position": "last real prompt token, post-block, pre-terminal-RMSNorm",
                "rtol": 0.01, "atol": 0.05}


def authorization_summary(problems, decisions, diagnostics):
    truth = np.asarray([p["authorization"] for p in problems], dtype=bool)
    decisions = np.asarray(decisions, dtype=bool)
    error = decisions != truth
    labels = np.asarray([p["file_label"] for p in problems], dtype=np.int64)
    counts = [int(np.sum(error & (labels == k))) for k in range(4)]
    probability_mass = np.asarray(diagnostics)[:, 3].astype(np.float64)
    valid_probability = np.isfinite(probability_mass) & (probability_mass >= 0) & (probability_mass <= 1)
    return {"n": len(problems), "errors": int(error.sum()), "correct": int((~error).sum()),
            "accuracy": float((~error).mean()), "error_rate": float(error.mean()),
            "errors_by_file_class": counts, "permitted_errors": int(np.sum(error & truth)),
            "forbidden_errors": int(np.sum(error & ~truth)),
            "first_token_compliance": float(np.mean(np.asarray(diagnostics)[:, 5])),
            "mean_binary_probability_mass": float(probability_mass[valid_probability].mean()) if valid_probability.any() else None,
            "binary_probability_mass_valid_n": int(valid_probability.sum()),
            "binary_probability_mass_excluded_diagnostic_n": int((~valid_probability).sum()),
            "authorization_cases_excluded": 0}


def pilot_selection(rows):
    # Protocol preferences refer to n=256. Scale ONLY for smoke documents.
    for row in rows:
        fraction = row["n"] / 256
        row["eligible"] = (
            math.ceil(32 * fraction) <= row["errors"] <= math.floor(102 * fraction)
            and all(k >= math.ceil(4 * fraction) for k in row["errors_by_file_class"])
            and row["permitted_errors"] >= math.ceil(8 * fraction)
            and row["forbidden_errors"] >= math.ceil(8 * fraction)
            and row["first_token_compliance"] >= 0.95
        )
    eligible = [r for r in rows if r["eligible"]]
    if eligible:
        chosen = min(eligible, key=lambda r: (abs(r["error_rate"] - 0.25),
                                             r["mean_prompt_tokens"], r["condition_index"]))
        rule = "eligible: error rate closest to 0.25, shorter tokenized prompt, condition index"
    else:
        candidates = [r for r in rows if r["accuracy"] >= 0.60]
        if candidates:
            chosen = min(candidates, key=lambda r: (-r["errors"], r["mean_prompt_tokens"], r["condition_index"]))
            rule = "fallback: most errors among accuracy >= 0.60, shorter prompt, condition index"
        else:
            # Continue the measurement even if the pilot signal is weak. This
            # diagnostic does not gate a measured held-out decoding shortfall.
            chosen = min(rows, key=lambda r: (-r["accuracy"], -r["errors"],
                                             r["mean_prompt_tokens"], r["condition_index"]))
            rule = "last fallback: highest authorization accuracy, most errors, shorter prompt, condition index"
    return {"condition": {"name_mode": chosen["name_mode"], "archive_count": chosen["archive_count"]},
            "condition_index": chosen["condition_index"], "selection_rule": rule,
            "strong_signal_established": bool(eligible),
            "selection_consulted_probe_results": False, "selection_consulted_test_results": False,
            "chosen_pilot_errors": chosen["errors"]}


def linear_classifier(C):
    kwargs = {"solver": "lbfgs", "C": C, "fit_intercept": True,
              "tol": 1e-5, "max_iter": 2000, "random_state": SEEDS["classifier"]}
    # sklearn 1.9 expresses L2 as l1_ratio=0; earlier installed versions use
    # penalty="l2". Inspect the live constructor instead of passing removed or
    # deprecated parameters based on an assumed version.
    parameters = inspect.signature(LogisticRegression).parameters
    if ("penalty" in parameters and parameters["penalty"].default == "deprecated"
            and "l1_ratio" in parameters):
        kwargs["l1_ratio"] = 0.0
    elif "penalty" in parameters:
        kwargs["penalty"] = "l2"
    for name in kwargs:
        if name not in parameters:
            raise RuntimeError(f"Installed LogisticRegression lacks required {name}: {parameters}")
    return LogisticRegression(**kwargs)


def fit_with_warnings(X, y, C):
    start = time.monotonic()
    model = linear_classifier(C)
    with warnings.catch_warnings(record=True) as recorded:
        warnings.simplefilter("always")
        model.fit(X, y)
    notices = [{"category": item.category.__name__, "message": str(item.message)} for item in recorded]
    for notice in notices:
        log(f"Probe fit warning: {notice['category']}: {notice['message']}")
    info = {"seconds": time.monotonic() - start,
            "iterations": np.asarray(model.n_iter_).tolist(),
            "converged": not any(issubclass(item.category, ConvergenceWarning) for item in recorded),
            "warnings": notices}
    assert np.isfinite(model.coef_).all() and np.isfinite(model.intercept_).all()
    assert list(model.classes_) == [0, 1, 2, 3]
    return model, info


def proportion(successes, total):
    successes, total = int(successes), int(total)
    assert 0 <= successes <= total
    if not total:
        return {"numerator": successes, "denominator": total, "accuracy": None,
                "ci_lower": None, "ci_upper": None, "ci_level": 0.95, "underpowered": True}
    z = float(norm.ppf(0.975))
    p = successes / total
    denominator = 1 + z * z / total
    center = (p + z * z / (2 * total)) / denominator
    radius = z * math.sqrt(p * (1 - p) / total + z * z / (4 * total * total)) / denominator
    return {"numerator": successes, "denominator": total, "accuracy": p,
            "ci_lower": min(p, max(0.0, center - radius)),
            "ci_upper": max(p, min(1.0, center + radius)),
            "ci_level": 0.95, "ci_method": "Wilson score",
            "underpowered": total < 100,
            "too_perfect_small_sample": successes == total and total < 100}


def sweep_probes(fitting_features, selection_features, fitting_problems,
                 selection_problems, selection_decisions, settings, identity):
    y_fit = np.asarray([p["file_label"] for p in fitting_problems], dtype=np.int64)
    y_selection = np.asarray([p["file_label"] for p in selection_problems], dtype=np.int64)
    truth = np.asarray([p["authorization"] for p in selection_problems], dtype=bool)
    error_mask = np.asarray(selection_decisions, dtype=bool) != truth
    directory = settings.out / "checkpoints" / "probe_sweep" / digest(identity)
    directory.mkdir(parents=True, exist_ok=True)
    rows = []
    for index in range(fitting_features.shape[1]):
        check_deadline(settings, f"probe layer {index + 1}")
        path = directory / f"layer_{index + 1:02d}.json"
        if path.exists():
            saved = json.loads(path.read_text())
            if saved.get("identity") == jsonable(identity) and len(saved.get("rows", [])) == len(C_VALUES):
                rows.extend(saved["rows"])
                log(f"Resumed fitted probe layer {index + 1}.")
                continue
        X_fit = np.array(fitting_features[:, index, :], dtype=np.float32, order="C")
        X_select = np.array(selection_features[:, index, :], dtype=np.float32, order="C")
        assert X_fit.ndim == 2 and np.isfinite(X_fit).all()
        assert np.any(np.var(X_fit, axis=0, dtype=np.float64) > 0)
        scaler = StandardScaler()
        X_fit = scaler.fit_transform(X_fit)
        X_select = scaler.transform(X_select)
        layer_rows = []
        for C in C_VALUES:
            check_deadline(settings, f"probe layer {index + 1}, C={C}")
            classifier, fit_info = fit_with_warnings(X_fit, y_fit, C)
            predicted = classifier.predict(X_select)
            correct = predicted == y_selection
            errors = int(error_mask.sum())
            row = {"layer": index + 1, "C": C, "selection_n": len(y_selection),
                   "selection_errors": errors, "overall_correct": int(correct.sum()),
                   "overall_accuracy": float(correct.mean()),
                   "error_correct": int(np.sum(correct & error_mask)),
                   "error_accuracy": float(correct[error_mask].mean()) if errors else None,
                   "fitting_accuracy": float(np.mean(classifier.predict(X_fit) == y_fit)),
                   **fit_info}
            layer_rows.append(row)
            log(f"Probe L{index + 1} C={C:g}: errors={row['error_correct']}/{errors}, "
                f"all={row['overall_accuracy']:.4f}, iterations={row['iterations']}")
        atomic_json(path, {"identity": identity, "rows": layer_rows})
        rows.extend(layer_rows)
        atomic_json(settings.out / "development_selection_table.json", rows)
        write_table(settings.out / "development_selection_table.csv", rows)
        del X_fit, X_select, scaler, classifier
        gc.collect()
    assert len(rows) == fitting_features.shape[1] * len(C_VALUES)
    atomic_json(settings.out / "development_selection_table.json", rows)
    write_table(settings.out / "development_selection_table.csv", rows)
    errors = int(error_mask.sum())
    # Integer numerators have a common denominator, giving exact tie ordering.
    chosen = max(rows, key=lambda row: (row["error_correct"] if errors else row["overall_correct"],
                                        row["overall_correct"], -row["C"], -row["layer"]))
    choice = {"layer": chosen["layer"], "C": chosen["C"], "selection_errors": errors,
              "selected_row": chosen,
              "rule": "error-only accuracy; overall accuracy; smaller C; lower layer",
              "zero_selection_errors_fallback": "overall accuracy" if not errors else None}
    return choice, rows


def decoder_arrays(scaler, classifier):
    coefficient = classifier.coef_.astype(np.float64) / scaler.scale_[None, :]
    intercept = classifier.intercept_.astype(np.float64) - coefficient @ scaler.mean_.astype(np.float64)
    arrays = {"standardized_coef": classifier.coef_, "standardized_intercept": classifier.intercept_,
              "scaler_mean": scaler.mean_, "scaler_scale": scaler.scale_, "scaler_variance": scaler.var_,
              "affine_coef": coefficient, "affine_intercept": intercept, "classes": classifier.classes_}
    assert all(np.isfinite(v).all() for v in arrays.values())
    return arrays


def predict_frozen(decoder, features):
    X = np.asarray(features, dtype=np.float64)
    score = X @ decoder["affine_coef"].T + decoder["affine_intercept"]
    assert score.shape == (len(X), 4) and np.isfinite(score).all()
    prediction = decoder["classes"][score.argmax(axis=1)].astype(np.int64)
    assert np.all((prediction >= 0) & (prediction <= 3))
    return prediction, score


def freeze_decoders(choice, fitting_features, selection_features, fitting_problems,
                    selection_problems, fitting_decisions, selection_decisions,
                    settings, identity):
    directory = settings.out / "frozen" / digest({"identity": identity, "choice": choice})
    directory.mkdir(parents=True, exist_ok=True)
    primary_path, negative_path = directory / "requested_file_decoder.npz", directory / "shuffled_decoder.npz"
    protocol_path = directory / "frozen_protocol.json"
    freeze_identity = {"identity": identity, "choice": choice}
    if protocol_path.exists():
        saved = json.loads(protocol_path.read_text())
        if (saved.get("freeze_identity") == jsonable(freeze_identity)
                and primary_path.exists() and negative_path.exists()
                and saved.get("primary_sha256") == sha256_file(primary_path)
                and saved.get("negative_sha256") == sha256_file(negative_path)):
            log("Using previously frozen decoders whose model, data, protocol, and artifact hashes match.")
            with np.load(primary_path, allow_pickle=False) as archive:
                primary = {k: archive[k].copy() for k in archive.files}
            with np.load(negative_path, allow_pickle=False) as archive:
                negative = {k: archive[k].copy() for k in archive.files}
            return primary, negative, saved, protocol_path
    check_deadline(settings, "frozen decoder refit")
    layer = choice["layer"] - 1
    X = np.concatenate((np.asarray(fitting_features[:, layer, :], dtype=np.float32),
                        np.asarray(selection_features[:, layer, :], dtype=np.float32)), axis=0)
    y = np.asarray([p["file_label"] for p in fitting_problems + selection_problems], dtype=np.int64)
    truths = np.asarray([p["authorization"] for p in fitting_problems + selection_problems], dtype=bool)
    decisions = np.concatenate((fitting_decisions, selection_decisions)).astype(bool)
    training_error = decisions != truths
    scaler = StandardScaler()
    standardized = scaler.fit_transform(X)
    classifier, fit_info = fit_with_warnings(standardized, y, choice["C"])
    primary = decoder_arrays(scaler, classifier)
    predicted, scores = predict_frozen(primary, X)
    sklearn_scores = classifier.decision_function(standardized)
    # Validate the affine composition numerically, rather than assume saved
    # preprocessing and classifier parameters were paired correctly.
    assert np.allclose(scores, sklearn_scores, rtol=2e-4, atol=2e-4)
    assert np.array_equal(predicted, classifier.predict(standardized))
    check_deadline(settings, "negative control refit")
    shuffled = np.random.default_rng(SEEDS["shuffled_labels"]).permutation(y)
    negative_classifier, negative_info = fit_with_warnings(standardized, shuffled, choice["C"])
    negative = decoder_arrays(scaler, negative_classifier)
    negative_prediction, _ = predict_frozen(negative, X)
    atomic_npz(primary_path, **primary)
    atomic_npz(negative_path, **negative)
    majority = int(np.bincount(y, minlength=4).argmax())
    protocol = {"freeze_identity": freeze_identity, "model": MODEL_ID,
                "model_revision": identity["revision"], "layer": choice["layer"], "C": choice["C"],
                "label_mapping": "0,1,2,3 identify zero-based file rows in the current table",
                "capture_convention": "raw block output at final real prompt token, before terminal RMSNorm",
                "decoder_type": "one four-class affine logistic regression, standardized on development only",
                "training_n": len(y), "training_initial_errors": int(training_error.sum()),
                "training_initial_correct": int((~training_error).sum()),
                "training_contains_correct_and_incorrect": bool(training_error.any() and (~training_error).any()),
                "training_file_accuracy": float(np.mean(predicted == y)),
                "training_error_file_accuracy": float(np.mean(predicted[training_error] == y[training_error])) if training_error.any() else None,
                "negative_training_accuracy_against_shuffled_labels": float(np.mean(negative_prediction == shuffled)),
                "primary_fit": fit_info, "negative_fit": negative_info,
                "shuffled_label_seed": SEEDS["shuffled_labels"],
                "shuffled_label_hash": digest(shuffled), "majority_label": majority,
                "primary_path": str(primary_path), "primary_sha256": sha256_file(primary_path),
                "negative_path": str(negative_path), "negative_sha256": sha256_file(negative_path),
                "test_used_for_training_or_selection": False,
                "frozen_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat()}
    atomic_json(protocol_path, protocol)
    atomic_json(settings.out / "frozen_protocol.json", {"path": str(protocol_path),
                                                       "sha256": sha256_file(protocol_path),
                                                       "protocol": protocol})
    log(f"Frozen L{choice['layer']} C={choice['C']:g} decoder on {len(y)} development examples.")
    return primary, negative, protocol, protocol_path


def holm_adjust(pvalues):
    adjusted = [None] * len(pvalues)
    valid = sorted((float(p), index) for index, p in enumerate(pvalues) if p is not None)
    running = 0.0
    for rank, (p, index) in enumerate(valid):
        running = max(running, min(1.0, (len(valid) - rank) * p))
        adjusted[index] = running
    return adjusted


def paired_bootstrap_gap(correct, initial_error, n_bootstrap=10000, seed=7100):
    rng = np.random.default_rng(seed)
    n = len(correct)
    values, undefined = [], 0
    for offset in range(0, n_bootstrap, 100):
        count = min(100, n_bootstrap - offset)
        draw = rng.integers(0, n, size=(count, n))
        error = initial_error[draw]
        success = correct[draw]
        ne = error.sum(axis=1)
        nc = n - ne
        usable = (ne > 0) & (nc > 0)
        undefined += int((~usable).sum())
        error_rate = (success & error).sum(axis=1)[usable] / ne[usable]
        correct_rate = (success & ~error).sum(axis=1)[usable] / nc[usable]
        values.extend((error_rate - correct_rate).tolist())
    return {"n_bootstrap": n_bootstrap, "seed": seed, "unit": "paired whole problems",
            "ci_level": 0.95, "ci_method": "percentile bootstrap",
            "ci_lower": float(np.percentile(values, 2.5)) if values else None,
            "ci_upper": float(np.percentile(values, 97.5)) if values else None,
            "undefined_replicates": undefined, "defined_replicates": len(values)}


def evaluate_test(problems, decisions, diagnostics, primary_prediction, negative_prediction,
                  protocol, smoke):
    y = np.asarray([p["file_label"] for p in problems], dtype=np.int64)
    truth = np.asarray([p["authorization"] for p in problems], dtype=bool)
    original = np.asarray(decisions, dtype=bool)
    initial_error_mask = original != truth
    correct = primary_prediction == y
    negative_correct = negative_prediction == y
    E = int(initial_error_mask.sum())
    K = int(np.sum(correct & initial_error_mask))
    required = (9 * E + 9) // 10  # integer ceil(0.90 * E)
    primary = proportion(K, E)
    primary["required_numerator"] = required
    primary["threshold"] = 0.90
    primary["finite_test_pass"] = bool(E > 0 and K >= required)
    overall = proportion(int(correct.sum()), len(y))
    initial_correct = proportion(int(np.sum(correct & ~initial_error_mask)), int((~initial_error_mask).sum()))
    negative = proportion(int(np.sum(negative_correct & initial_error_mask)), E)
    majority_correct = y == protocol["majority_label"]
    majority = proportion(int(np.sum(majority_correct & initial_error_mask)), E)
    confusion = np.zeros((4, 4), dtype=np.int64)
    np.add.at(confusion, (y[initial_error_mask], primary_prediction[initial_error_mask]), 1)
    invariants = {"confusion_counts_nonnegative": bool(np.all(confusion >= 0)),
                  "confusion_total_and_trace": int(confusion.sum()) == E and int(np.trace(confusion)) == K}
    by_class = {str(label): proportion(int(np.sum(correct & initial_error_mask & (y == label))),
                                      int(np.sum(initial_error_mask & (y == label)))) for label in range(4)}
    by_decision = {name: proportion(int(np.sum(correct & initial_error_mask & (truth == flag))),
                                   int(np.sum(initial_error_mask & (truth == flag))))
                   for name, flag in (("permitted", True), ("forbidden", False))}
    invariants.update({"file_class_denominators_cover_all_errors": sum(row["denominator"] for row in by_class.values()) == E,
                       "file_class_numerators_match_primary": sum(row["numerator"] for row in by_class.values()) == K,
                       "authorization_subgroup_denominators_cover_all_errors": sum(row["denominator"] for row in by_decision.values()) == E})
    discordant_true_only = int(np.sum(initial_error_mask & correct & ~negative_correct))
    discordant_negative_only = int(np.sum(initial_error_mask & ~correct & negative_correct))
    binomial_p = float(binomtest(K, E, p=0.90, alternative="two-sided").pvalue) if E else None
    discordant = discordant_true_only + discordant_negative_only
    mcnemar_p = (float(binomtest(discordant_true_only, discordant, p=0.5, alternative="two-sided").pvalue)
                 if discordant else 1.0) if E else None
    adjusted = holm_adjust([binomial_p, mcnemar_p])
    gap = (primary["accuracy"] - initial_correct["accuracy"]
           if primary["accuracy"] is not None and initial_correct["accuracy"] is not None else None)
    statistics = {
        "binomial_threshold_test": {"null_accuracy": 0.90, "alternative": "two-sided",
                                    "p_value": binomial_p, "holm_p_value": adjusted[0]},
        "exact_mcnemar_true_vs_shuffled": {"true_only_correct": discordant_true_only,
                                          "shuffled_only_correct": discordant_negative_only,
                                          "discordant_total": discordant,
                                          "p_value": mcnemar_p, "holm_p_value": adjusted[1]},
        "multiple_testing": {"method": "Holm", "family": ["binomial_threshold_test", "exact_mcnemar_true_vs_shuffled"],
                             "development_sweeps": "selection, not confirmatory tests"},
        "accuracy_gap_error_minus_correct": {"effect_size": gap,
                                               **paired_bootstrap_gap(correct, initial_error_mask,
                                                                      10000, SEEDS["bootstrap"])},
        "error_accuracy_above_uniform_guess_percentage_points":
            100 * (primary["accuracy"] - 0.25) if E else None,
        "overall_accuracy_above_uniform_guess_percentage_points": 100 * (overall["accuracy"] - 0.25),
    }
    bootstrap = statistics["accuracy_gap_error_minus_correct"]
    invariants.update({"accuracy_gap_range": gap is None or -1 <= gap <= 1,
                       "bootstrap_replicate_accounting": bootstrap["defined_replicates"] + bootstrap["undefined_replicates"] == 10000,
                       "bootstrap_interval_range": bootstrap["ci_lower"] is None or
                       -1 <= bootstrap["ci_lower"] <= bootstrap["ci_upper"] <= 1})
    reasons = []
    if E == 0:
        reasons.append("No initial test authorization errors; conditional denominator is zero.")
    if protocol["training_initial_errors"] == 0:
        reasons.append("No incorrect development runs in final decoder training.")
    if protocol["training_initial_correct"] == 0:
        reasons.append("No correct development runs in final decoder training.")
    if smoke:
        reasons.append("SMOKE is a reduced execution check, not the 1,200-case commissioned measurement.")
    verdict = "INCONCLUSIVE" if reasons else "SUPPORTED" if primary["finite_test_pass"] else "NOT_SUPPORTED"
    if E:
        evidence = ("strong_against_threshold" if primary["ci_upper"] < 0.90 else
                    "strong_support_for_threshold" if primary["ci_lower"] > 0.90 else
                    "interval_crosses_threshold")
    else:
        evidence = "undefined_zero_denominator"
    summary = {"subclaim": "sc3", "experiment": "515-sc3", "verdict": verdict,
               "scope": "This requested-file decoder implementation; does not decide all configurations of an existential claim.",
               "threshold": 0.90, "numerator": K, "denominator": E,
               "required_numerator": required, "primary_accuracy": primary["accuracy"],
               "finite_test_threshold_met": primary["finite_test_pass"],
               "overall_file_accuracy": overall["accuracy"],
               "authorization_accuracy": float((~initial_error_mask).mean()),
               "test_n": len(y), "specified_test_n": 1200,
               "ci_lower": primary["ci_lower"], "ci_upper": primary["ci_upper"],
               "confidence_interval_evidence": evidence, "underpowered": primary["underpowered"],
               "inconclusive_reasons": reasons, "smoke": smoke,
               "recipient_decoding_tested": False, "attention_head_patching_tested": False,
               "untested_criteria": ["permitted-recipient decoding", "head-patching error correction", "correct-decision preservation"]}
    metrics = {"primary_error_only_file_accuracy": primary, "overall_file_accuracy": overall,
               "initially_correct_file_accuracy": initial_correct,
               "authorization": authorization_summary(problems, decisions, diagnostics),
               "error_confusion_matrix": confusion, "confusion_orientation": "true rows, predicted columns; class order 0,1,2,3",
               "error_by_file_class": by_class, "error_by_authorization_category": by_decision,
               "negative_control_error_only": negative,
               "negative_control_overall": proportion(int(negative_correct.sum()), len(y)),
               "development_majority_control_error_only": majority,
               "development_majority_control_overall": proportion(int(majority_correct.sum()), len(y)),
               "uniform_guess_expectation": 0.25, "invariant_checks": invariants}
    invariants.update({"prediction_and_decision_counts": len(primary_prediction) == len(problems) == len(decisions) == len(negative_prediction),
                       "all_original_errors_in_mask": bool(np.array_equal(initial_error_mask, original != truth)),
                       "specified_test_size_and_balance": smoke or (len(problems) == 1200 and int(truth.sum()) == 600),
                       "primary_count_range": K <= E <= len(problems) and required <= E})
    return summary, metrics, statistics, initial_error_mask


def validate_results(obj, trail="results"):
    """Aggregate checks; callers catch and record failures AFTER writing evidence."""
    bounded_names = {"accuracy", "error_rate", "first_token_compliance", "mean_binary_probability_mass",
                     "primary_accuracy", "overall_file_accuracy", "authorization_accuracy", "threshold",
                     "uniform_guess_expectation", "p_value", "holm_p_value", "null_accuracy", "ci_level"}
    nonnegative_names = {"numerator", "denominator", "required_numerator", "n", "errors", "correct",
                         "test_n", "specified_test_n", "training_n", "training_initial_errors",
                         "training_initial_correct", "discordant_total", "true_only_correct", "shuffled_only_correct",
                         "n_bootstrap", "undefined_replicates", "defined_replicates", "completed"}
    if isinstance(obj, dict):
        for key, value in obj.items():
            key = str(key)
            if isinstance(value, (int, float, np.number)) and not isinstance(value, (bool, np.bool_)):
                assert math.isfinite(float(value)), f"Nonfinite metric at {trail}.{key}"
                if key in bounded_names or key.endswith("_accuracy"):
                    assert 0 <= float(value) <= 1, f"Invalid probability at {trail}.{key}: {value}"
                if key in nonnegative_names:
                    assert float(value) >= 0, f"Negative count at {trail}.{key}"
            validate_results(value, f"{trail}.{key}")
        if {"numerator", "denominator", "accuracy"}.issubset(obj):
            assert 0 <= obj["numerator"] <= obj["denominator"]
            if obj["denominator"]:
                assert 0 <= obj["ci_lower"] <= obj["accuracy"] <= obj["ci_upper"] <= 1
                assert math.isclose(obj["accuracy"], obj["numerator"] / obj["denominator"], abs_tol=1e-12)
            else:
                assert obj["accuracy"] is None
    elif isinstance(obj, (list, tuple)):
        for index, value in enumerate(obj):
            validate_results(value, f"{trail}[{index}]")
    elif isinstance(obj, np.ndarray):
        assert np.isfinite(obj).all(), f"Nonfinite array at {trail}"
        validate_results(obj.tolist(), trail)
    elif isinstance(obj, (float, np.floating)):
        assert math.isfinite(float(obj)), f"Nonfinite number at {trail}"


def write_then_validate_results(path, results, serialization_issues, aggregate_checks):
    """Persist evidence first, then annotate validation without throwing it away."""
    issues = list(serialization_issues)
    clean = finite_payload(results, issues, "results")
    clean["validation"] = {
        "status": "pending", "non_finite_fields": issues, "n_masked_values": len(issues),
        "n_dropped": 0, "authorization_cases_excluded": 0,
        "diagnostic_violations": [{"phase": name, **v}
                                  for name, phase in clean.get("diagnostics", {}).get("inference_phases", {}).items()
                                  for v in phase.get("validation", {}).get("diagnostic_violations", [])],
        "aggregate_checks": [],
        "probability_mass_method": "float64 max-shifted positive numerator/full-vocabulary denominator",
    }
    atomic_json(path, clean)
    failures = []
    checks = [("finite_metrics_valid_ranges_and_count_identities", lambda: validate_results(clean))]
    checks.extend(aggregate_checks)
    for name, check in checks:
        try:
            passed = check()
            if passed is not None and not bool(passed):
                raise AssertionError(name)
        except Exception as exc:
            failure = {"name": name, "passed": False, "error_type": type(exc).__name__, "reason": str(exc)}
            clean["validation"]["aggregate_checks"].append(failure)
            failures.append(failure)
            log(f"Recorded aggregate validation failure after preserving results: {name}: {exc}")
        else:
            clean["validation"]["aggregate_checks"].append({"name": name, "passed": True})
    clean["validation"]["status"] = "failed" if failures else "warnings" if (
        issues or clean["validation"]["diagnostic_violations"]) else "passed"
    if failures:
        clean["summary"]["verdict"] = "INCONCLUSIVE"
        clean["summary"].setdefault("inconclusive_reasons", []).append(
            "Aggregate result validation failed; measurements and failure details have been retained.")
    clean["summary"]["validation_status"] = clean["validation"]["status"]
    atomic_json(path, clean)
    return clean


def package_versions():
    names = ("torch", "transformers", "huggingface_hub", "numpy", "scipy", "scikit-learn", "threadpoolctl")
    versions = {}
    for name in names:
        try:
            versions[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            versions[name] = "unknown"
    return versions


def runtime_diagnostics(settings, device):
    result = {"elapsed_seconds": time.monotonic() - START_MONOTONIC,
              "python": sys.version, "package_versions": package_versions(),
              "device": str(device), "allocated_cpus_used": settings.cpus,
              "walltime_seconds": settings.walltime, "hf_home": os.environ["HF_HOME"],
              "hf_hub_cache": os.environ["HF_HUB_CACHE"], "base": str(BASE),
              "gpu_name": None, "peak_gpu_allocated_bytes": 0, "peak_gpu_reserved_bytes": 0}
    if device.type == "cuda":
        result["gpu_name"] = torch.cuda.get_device_name(device)
        result["peak_gpu_allocated_bytes"] = int(torch.cuda.max_memory_allocated(device))
        result["peak_gpu_reserved_bytes"] = int(torch.cuda.max_memory_reserved(device))
    return result


def protocol_definition(settings, revision):
    return {"script_version": SCRIPT_VERSION, "script_sha256": sha256_file(Path(__file__)),
            "model_id": MODEL_ID, "revision": revision, "precision": "bfloat16", "attention": "sdpa",
            "dataset": DATASET_ID, "seeds": SEEDS, "sizes": settings.sizes,
            "smoke": settings.smoke, "prompt_policy": SYSTEM_POLICY,
            "assignment_partition": "coordinate sum mod four: fitting/pilot {0,1}, selection {2}, test {3}",
            "label_mapping": "zero-based current permission-table file row",
            "archive_counts": [0, 8, 32, 128], "name_modes": ["distinct", "confusable"],
            "authorization": "larger Yes/No next-token logit, tie No",
            "probability_mass_diagnostic": "float64 max-shifted positive numerator/full-vocabulary denominator",
            "capture": "each block's raw output, final prompt token, before terminal RMS normalization",
            "regularization_C": C_VALUES, "probe_solver": "lbfgs", "penalty": "L2",
            "probe_tolerance": 1e-5, "probe_max_iter": 2000,
            "selection": "all selection errors, then overall accuracy, smaller C, lower layer",
            "refit": "fitting + development selection, before test inference",
            "shuffled_label_control": "one global seed-fixed permutation of all development labels",
            "bootstrap_resamples": 10000,
            "scope": "requested-file accuracy, especially all initial authorization errors; no recipient or patching test"}


def run_experiment(settings, state):
    random.seed(42)
    np.random.seed(42)
    torch.manual_seed(42)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(42)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    torch.set_num_threads(settings.cpus)
    if device.type == "cuda":
        torch.backends.cuda.matmul.allow_tf32 = False
        torch.backends.cudnn.allow_tf32 = False
        torch.backends.cudnn.benchmark = False
        torch.cuda.reset_peak_memory_stats(device)
    # SDPA kernels are deterministic for this fixed inference configuration;
    # repeated-decision checks below measure this rather than assuming it.
    state["device"] = str(device)
    state["phase"] = "asset_resolution"
    config, tokenizer, revision, provenance = resolve_assets()
    definition = protocol_definition(settings, revision)
    protocol_hash = digest(definition)
    atomic_json(settings.out / "protocol_definition.json", {"sha256": protocol_hash, "definition": definition})
    state.update({"model": provenance, "protocol_hash": protocol_hash, "sizes": settings.sizes})
    used_names = set()
    pilot_groups, manifests = {}, {}
    conditions = [{"archive_count": archive_count, "name_mode": name_mode}
                  for archive_count in (0, 8, 32, 128) for name_mode in ("distinct", "confusable")]
    for index, condition in enumerate(conditions):
        name = f"pilot_{index}"
        problems = generate_balanced_split(name, settings.sizes["pilot_per_condition"], condition,
                                           SEEDS["pilot"] + index, used_names)
        pilot_groups[name] = problems
        manifests[name] = save_manifest(settings.out, name, problems)
    controls = generate_controls(settings.sizes["controls"], used_names)
    manifests["controls"] = save_manifest(settings.out, "controls", controls)
    state["phase"] = "model_loading"
    check_deadline(settings, "model load")
    log(f"Loading security-evaluation model {MODEL_ID}@{revision}, bfloat16, device={device}.")
    model = load_named_model(config, revision, device)
    vocabulary = choose_response_vocabulary(tokenizer)
    engine = InferenceEngine(model, tokenizer, vocabulary, settings, revision, protocol_hash)
    dimension_audit = {"expected_blocks": 28, "observed_blocks": engine.n_layers,
                       "expected_residual_width": 3584, "observed_residual_width": engine.width,
                       "matches_expected": engine.n_layers == 28 and engine.width == 3584,
                       "model_class": type(model).__name__, "weights_frozen": all(not p.requires_grad for p in model.parameters()),
                       "evaluation_mode": not model.training, "use_cache": model.config.use_cache}
    assert dimension_audit["weights_frozen"] and dimension_audit["evaluation_mode"]
    state["phase"] = "readout_validation"
    readout_validation = engine.validate_readout(controls)
    state["phase"] = "pilot"
    pilot_rows, inference_phases = [], {}
    for index, condition in enumerate(conditions):
        name = f"pilot_{index}"
        decisions, diagnostics, _, phase = engine.infer_problems(pilot_groups[name], [], name,
                                                                 manifests[name]["sha256"])
        inference_phases[name] = phase
        row = {"condition_index": index, **condition,
               **authorization_summary(pilot_groups[name], decisions, diagnostics),
               "mean_prompt_tokens": engine.token_audits[name]["mean"]}
        pilot_rows.append(row)
        atomic_json(settings.out / "pilot_table.json", pilot_rows)
        write_table(settings.out / "pilot_table.csv", pilot_rows)
    selected_prompt = pilot_selection(pilot_rows)
    atomic_json(settings.out / "selected_prompt.json", selected_prompt)
    # Re-write after attaching every candidate's eligibility information.
    atomic_json(settings.out / "pilot_table.json", pilot_rows)
    write_table(settings.out / "pilot_table.csv", pilot_rows)
    log(f"Selected prompt by authorization behavior only: {selected_prompt}")
    state["phase"] = "controls"
    control_decisions, control_diagnostics, _, control_phase = engine.infer_problems(
        controls, [], "controls", manifests["controls"]["sha256"])
    inference_phases["controls"] = control_phase
    control_summary = authorization_summary(controls, control_decisions, control_diagnostics)
    pairs = np.asarray(control_decisions).reshape(-1, 2)
    control_summary.update({"pairs": len(pairs), "recipient_change_decision_flip_rate": float(np.mean(pairs[:, 0] != pairs[:, 1])),
                            "both_decisions_correct_rate": float(np.mean((pairs[:, 0] == 1) & (pairs[:, 1] == 0))),
                            "interpretation": "Decision extraction/recipient sensitivity diagnostic; does not gate the held-out result."})
    state["phase"] = "generation"
    # Reserve held-out names before generating either large development split.
    test_problems = generate_balanced_split("test", settings.sizes["test"], selected_prompt["condition"],
                                            SEEDS["test"], used_names)
    fitting_problems = generate_balanced_split("fitting", settings.sizes["fitting"], selected_prompt["condition"],
                                               SEEDS["fitting"], used_names)
    selection_problems = generate_balanced_split("selection", settings.sizes["selection"], selected_prompt["condition"],
                                                 SEEDS["selection"], used_names)
    groups = {**pilot_groups, "controls": controls, "fitting": fitting_problems,
              "selection": selection_problems, "test": test_problems}
    for name in ("test", "fitting", "selection"):
        manifests[name] = save_manifest(settings.out, name, groups[name])
    integrity = generation_integrity(groups, not settings.smoke)
    # Tokenize all generated documents before extraction. No truncation is used.
    for name in ("fitting", "selection", "test"):
        engine.encode_problems(groups[name], name)
    atomic_json(settings.out / "generation_provenance.json", {"dataset": DATASET_ID, "manifests": manifests,
                                                            "integrity": integrity, "token_audits": engine.token_audits,
                                                            "source": "in-script task generator, no external data or human annotation"})
    atomic_json(settings.out / "run_identity.json", {"revision": revision, "protocol_hash": protocol_hash,
                                                   "manifest_hashes": {k: v["sha256"] for k, v in manifests.items()}})
    state["manifest_hashes"] = {k: v["sha256"] for k, v in manifests.items()}
    layers = list(range(1, engine.n_layers + 1))
    state["phase"] = "fitting_feature_extraction"
    fitting_decisions, fitting_diagnostics, fitting_features, fitting_phase = engine.infer_problems(
        fitting_problems, layers, "fitting", manifests["fitting"]["sha256"])
    inference_phases["fitting"] = fitting_phase
    state["phase"] = "selection_feature_extraction"
    selection_decisions, selection_diagnostics, selection_features, selection_phase = engine.infer_problems(
        selection_problems, layers, "selection", manifests["selection"]["sha256"])
    inference_phases["selection"] = selection_phase
    fitting_authorization = authorization_summary(fitting_problems, fitting_decisions, fitting_diagnostics)
    selection_authorization = authorization_summary(selection_problems, selection_decisions, selection_diagnostics)
    identity = {"revision": revision, "protocol_hash": protocol_hash,
                "fitting_manifest": manifests["fitting"]["sha256"], "selection_manifest": manifests["selection"]["sha256"],
                "fitting_inference": fitting_phase["identity_hash"], "selection_inference": selection_phase["identity_hash"],
                "feature_shape": list(fitting_features.shape), "C_values": C_VALUES,
                "selection_error_mask_hash": digest(np.asarray(selection_decisions, dtype=bool) !=
                                                    np.asarray([p["authorization"] for p in selection_problems], dtype=bool))}
    state["phase"] = "probe_sweep"
    with threadpool_limits(limits=settings.cpus):
        choice, sweep_rows = sweep_probes(fitting_features, selection_features, fitting_problems,
                                          selection_problems, selection_decisions, settings, identity)
        state["phase"] = "decoder_freezing"
        primary, negative, frozen_protocol, frozen_path = freeze_decoders(
            choice, fitting_features, selection_features, fitting_problems, selection_problems,
            fitting_decisions, selection_decisions, settings, identity)
    frozen_hash_before = sha256_file(frozen_path)
    primary_hash_before = sha256_file(frozen_protocol["primary_path"])
    negative_hash_before = sha256_file(frozen_protocol["negative_path"])
    del fitting_features, selection_features
    gc.collect()
    state["phase"] = "held_out_inference"
    state["frozen_protocol_path"] = str(frozen_path)
    # Test inference starts only after writing frozen artifacts. Its checkpoint
    # identity additionally commits to those exact artifacts.
    engine.protocol_hash = digest({"base_protocol_hash": protocol_hash,
                                   "frozen_protocol_sha256": frozen_hash_before,
                                   "primary_sha256": primary_hash_before, "negative_sha256": negative_hash_before})
    state["test_inference_protocol_hash"] = engine.protocol_hash
    test_decisions, test_diagnostics, test_features, test_phase = engine.infer_problems(
        test_problems, [choice["layer"]], "test", manifests["test"]["sha256"])
    inference_phases["test"] = test_phase
    test_inference_complete = test_phase["completed"] == len(test_problems)
    state["test_completed"] = len(test_problems)
    state["phase"] = "held_out_statistics"
    with threadpool_limits(limits=settings.cpus):
        prediction, probe_scores = predict_frozen(primary, test_features[:, 0, :])
        negative_prediction, _ = predict_frozen(negative, test_features[:, 0, :])
    summary, metrics, statistics, error_mask = evaluate_test(
        test_problems, test_decisions, test_diagnostics, prediction, negative_prediction,
        frozen_protocol, settings.smoke)
    frozen_unchanged = (sha256_file(frozen_path) == frozen_hash_before
                        and sha256_file(frozen_protocol["primary_path"]) == primary_hash_before
                        and sha256_file(frozen_protocol["negative_path"]) == negative_hash_before)
    integrity.update({"test_errors_in_primary_denominator": int(error_mask.sum()),
                      "test_errors_removed": 0, "frozen_artifacts_unchanged_during_test": frozen_unchanged,
                      "test_inference_after_frozen_protocol": True,
                      "features_are_original_unpatched_states": True,
                      "no_test_refitting_or_reselection": True})
    predictions = []
    for index, problem in enumerate(test_problems):
        diag = {key: float(test_diagnostics[index, col]) for col, key in enumerate(DIAG_COLUMNS)}
        diag["unrestricted_argmax_token_id"] = int(diag["unrestricted_argmax_token_id"])
        diag["first_token_compliant"] = bool(diag["first_token_compliant"])
        predictions.append({"id": problem["id"], "ground_truth_authorization": problem["authorization"],
                            "original_authorization": bool(test_decisions[index]),
                            "initial_authorization_error": bool(error_mask[index]),
                            "ground_truth_file_row": problem["file_label"], "predicted_file_row": int(prediction[index]),
                            "predicted_filename": problem["files"][prediction[index]],
                            "true_requested_filename": problem["files"][problem["file_label"]],
                            "negative_control_file_row": int(negative_prediction[index]),
                            "probe_class_scores": probe_scores[index].tolist(), **diag})
    serialization_issues = []
    clean_predictions = finite_payload(predictions, serialization_issues, "test_predictions")
    prediction_hash = write_jsonl(settings.out / "test_predictions.jsonl", clean_predictions)
    model_diagnostics = {"dimensions": dimension_audit, "api_signatures": engine.api,
                         "response_vocabulary": vocabulary, "readout_validation": readout_validation,
                         "controls": control_summary, "pilot_signal": selected_prompt,
                         "fitting_authorization": fitting_authorization,
                         "selection_authorization": selection_authorization,
                         "probe_training": {"contains_correct_and_incorrect": frozen_protocol["training_contains_correct_and_incorrect"],
                                            "correct_runs": frozen_protocol["training_initial_correct"],
                                            "incorrect_runs": frozen_protocol["training_initial_errors"],
                                            "seen_development_file_accuracy": frozen_protocol["training_file_accuracy"],
                                            "converged_sweep_fits": sum(bool(r["converged"]) for r in sweep_rows),
                                            "total_sweep_fits": len(sweep_rows)},
                         "token_audits": engine.token_audits, "inference_phases": inference_phases,
                         "oom_events": engine.oom_events}
    assumptions = ["An index of the file's current-table row is the prespecified name-independent requested-file label.",
                   "Forced-choice Yes/No next-token logits operationalize authorization independently of response wording.",
                   "This single generated task/template and decoder search cannot exclude other existential configurations."]
    if not dimension_audit["matches_expected"]:
        assumptions.append("Checkpoint configuration dimensions differ from the expected 28 blocks / width 3584; observed dimensions are reported.")
    if not vocabulary["single_token_verified"]:
        assumptions.append(vocabulary["assumption"])
    results = {"summary": summary, "proxy": None, "results": metrics, "statistical_tests": statistics,
               "artifact_versions": {"models": [{"id": MODEL_ID, "revision": revision,
                                                   "requested_revision": MODEL_REVISION, "precision": "bfloat16"}],
                                     "dataset": {"name": DATASET_ID, "generator_version": SCRIPT_VERSION,
                                                 "source": "script-generated claim task", "seeds": SEEDS}},
               "provenance": provenance, "protocol": definition, "protocol_hash": protocol_hash,
               "manifests": manifests, "integrity": integrity, "diagnostics": model_diagnostics,
               "selected_decoder": choice, "frozen_protocol": frozen_protocol,
               "artifacts": {"frozen_protocol": str(frozen_path), "frozen_protocol_sha256": frozen_hash_before,
                             "test_predictions": str(settings.out / "test_predictions.jsonl"),
                             "test_predictions_sha256": prediction_hash,
                             "pilot_table": str(settings.out / "pilot_table.json"),
                             "development_selection_table": str(settings.out / "development_selection_table.json")},
               "assumptions": assumptions, "runtime": runtime_diagnostics(settings, device),
               "recipient_decoding_and_patching": "NOT TESTED: outside this sc3 specification."}
    # The commissioned finite-test verdict is NEVER replaced by an interval,
    # pilot preference, epoch count, token cap, or convergence warning. Actual
    # aggregate result-identity failures are annotated AFTER evidence is saved.
    checks = [
        ("complete_test_inference", lambda: test_inference_complete),
        ("frozen_decoders_unchanged_during_test", lambda: frozen_unchanged),
    ]
    checks.extend((name, lambda value=value: value) for name, value in metrics["invariant_checks"].items())
    if not settings.smoke and not summary["inconclusive_reasons"]:
        checks.append(("finite_test_threshold_verdict", lambda:
                       (summary["verdict"] == "SUPPORTED") ==
                       metrics["primary_error_only_file_accuracy"]["finite_test_pass"]))
    results = write_then_validate_results(BASE / "results_sc3.json", results, serialization_issues, checks)
    summary = results["summary"]
    state["phase"] = "complete"
    atomic_json(settings.out / "execution_state.json", state)
    log(f"sc3 {summary['verdict']}: requested-file predictions {summary['numerator']}/{summary['denominator']} "
        f"on initial errors; test n={summary['test_n']}. Results: {BASE / 'results_sc3.json'}")


def main():
    settings = settings_from_cli()
    state = {"script_version": SCRIPT_VERSION, "phase": "initialization", "smoke": settings.smoke,
             "test_completed": 0, "started_utc": datetime.datetime.now(datetime.timezone.utc).isoformat()}
    for number in (signal.SIGTERM, signal.SIGINT):
        signal.signal(number, on_signal)
    if hasattr(signal, "SIGUSR1"):
        signal.signal(signal.SIGUSR1, on_signal)
    atomic_json(settings.out / "execution_state.json", state)
    try:
        with threadpool_limits(limits=settings.cpus):
            run_experiment(settings, state)
    except DeadlineReached as exc:
        # Checkpoints permit a new invocation to finish this whole experiment.
        # A partially inferred test set is never treated as the 1,200-case result.
        if state["phase"] == "held_out_inference":
            completed = []
            checkpoint_root = settings.out / "checkpoints" / "test"
            if checkpoint_root.exists():
                for progress in checkpoint_root.glob("*/progress.json"):
                    value = json.loads(progress.read_text())
                    identity = value["identity"]
                    if (identity.get("protocol_hash") == state.get("test_inference_protocol_hash")
                            and identity.get("revision") == state.get("model", {}).get("full_revision")
                            and identity.get("manifest_hash") == state.get("manifest_hashes", {}).get("test")):
                        completed.append(int(value.get("completed", 0)))
            state["test_completed"] = max(completed, default=0)
        result = {"summary": {"experiment": "515-sc3", "subclaim": "sc3", "verdict": "INCOMPLETE",
                              "reason": str(exc), "phase": state["phase"],
                              "test_completed": state["test_completed"], "specified_test_n": 1200,
                              "smoke": settings.smoke, "recipient_decoding_tested": False,
                              "attention_head_patching_tested": False},
                  "proxy": None, "execution_state": state,
                  "runtime": {"elapsed_seconds": time.monotonic() - START_MONOTONIC},
                  "measured_test_metrics": None}
        write_then_validate_results(BASE / "results_sc3.json", result, [], [])
        atomic_json(settings.out / "execution_state.json", state)
        log(f"INCOMPLETE: {exc}; phase={state['phase']}; preserving resumable checkpoints.")
        return 2
    except Exception as exc:
        # Never delete completed evidence because a later audit/serialization
        # operation failed. Attach the failure to the retained payload instead.
        result_path = BASE / "results_sc3.json"
        if result_path.exists():
            try:
                retained = json.loads(result_path.read_text())
                retained.setdefault("validation", {}).setdefault("execution_failures", []).append(
                    {"error_type": type(exc).__name__, "reason": str(exc), "phase": state["phase"]})
                atomic_json(result_path, retained)
            except Exception as preservation_error:
                log(f"Existing results retained; could not annotate later failure: {preservation_error}")
        atomic_json(settings.out / "failure_sc3.json", {"error_type": type(exc).__name__, "error": str(exc),
                                                       "state": state, "traceback": traceback.format_exc()})
        traceback.print_exc()
        log(f"FAILED security evaluation: {type(exc).__name__}: {exc}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

