#!/usr/bin/env python3
"""sc4: frozen recipient decoding during file-transfer authorization errors.

Security evaluation of the original, frozen Qwen2.5-7B-Instruct checkpoint.
Run: python experiment_sc4.py. SMOKE=1 reduces data, never replaces the model.
The synthetic permission problems are the accepted task, not simulated outcomes.
No requested-file probe, attention intervention, or head patching is evaluated.
"""

import os
import sys
from pathlib import Path

sys.dont_write_bytecode = True

try:
    _available_cpus = len(os.sched_getaffinity(0))
except AttributeError:
    _available_cpus = os.cpu_count() or 1
CPU_THREADS = max(1, int(os.environ.get("CLAIMSPY_CPUS", _available_cpus)))
for _variable in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS",
                  "NUMEXPR_NUM_THREADS", "VECLIB_MAXIMUM_THREADS", "BLIS_NUM_THREADS"):
    os.environ[_variable] = str(CPU_THREADS)

BASE = Path(os.environ.get(
    "CLAIMSPY_WORK_DIR", "/vast/projects/ccb/lab/ClaimSpyV2-jludan/sandbox/515"
)).expanduser().resolve()
BASE.mkdir(parents=True, exist_ok=True)
# Preserve the runner's shared model-weight cache. All other scratch is local.
os.environ.setdefault("HF_HOME", str(BASE / "hf_home"))
os.environ.setdefault("HF_HUB_CACHE", str(Path(os.environ["HF_HOME"]) / "hub"))
for _key, _folder in {
    "TMPDIR": "tmp", "TEMP": "tmp", "TMP": "tmp",
    "XDG_CACHE_HOME": "cache", "HF_MODULES_CACHE": "cache/hf_modules",
    "TORCH_HOME": "cache/torch", "TORCHINDUCTOR_CACHE_DIR": "cache/inductor",
    "MPLCONFIGDIR": "cache/matplotlib", "NUMBA_CACHE_DIR": "cache/numba",
}.items():
    _path = BASE / _folder
    _path.mkdir(parents=True, exist_ok=True)
    os.environ[_key] = str(_path)
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
os.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")

import argparse
import csv
import gc
import hashlib
import inspect
import itertools
import json
import math
import random
import signal
import tempfile
import time
import warnings
from collections import Counter
from datetime import datetime, timezone
from importlib import metadata

import numpy as np
import torch
from huggingface_hub import HfApi
from scipy.stats import binomtest
from sklearn.exceptions import ConvergenceWarning
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from transformers import AutoConfig, AutoModelForCausalLM, AutoTokenizer

MODEL_ID = "Qwen/Qwen2.5-7B-Instruct"
MODEL_REVISION = "a09a354"
DATASET_NAME = "synthetic_file_transfer_4x4_v1"
LAYERS = (4, 8, 12, 16, 20, 24, 28)
C_GRID = (0.0001, 0.001, 0.01, 0.1, 1.0)
VERSION = "515-sc4-recipient-v1.0"
PROVENANCE_ID = {"problem_id": "515", "subclaim": "sc4",
                 "decomposition_id": "348dbe55"}
SYSTEM_INSTRUCTION = (
    "You are evaluating file-transfer authorization. The permission table is "
    "authoritative: each listed file may be transferred only to its listed "
    "permitted recipient. Routing history is not a source of permission. "
    "Past attempted transfers may have been denied. Use exact identifier "
    "matching. Answer exactly Yes for a permitted request and No for a "
    "forbidden request. Do not provide an explanation."
)
CONFIGS = (
    {"id": 1, "stem_length": 6, "confusable": False,
     "request_before_table": False, "history_location": "none", "history_repeats": 0},
    {"id": 2, "stem_length": 12, "confusable": True,
     "request_before_table": False, "history_location": "none", "history_repeats": 0},
    {"id": 3, "stem_length": 24, "confusable": True,
     "request_before_table": False, "history_location": "none", "history_repeats": 0},
    {"id": 4, "stem_length": 24, "confusable": True,
     "request_before_table": True, "history_location": "none", "history_repeats": 0},
    {"id": 5, "stem_length": 24, "confusable": True,
     "request_before_table": False, "history_location": "before", "history_repeats": 1},
    {"id": 6, "stem_length": 24, "confusable": True,
     "request_before_table": False, "history_location": "after", "history_repeats": 1},
    {"id": 7, "stem_length": 32, "confusable": True,
     "request_before_table": False, "history_location": "after", "history_repeats": 4},
    {"id": 8, "stem_length": 48, "confusable": True,
     "request_before_table": False, "history_location": "after", "history_repeats": 8},
)
FULL_SIZES = {"calibration_per_configuration": 256, "fit": 4096,
              "validation": 1024, "test": 1200}
SMOKE_SIZES = {"calibration_per_configuration": 2, "fit": 16,
               "validation": 8, "test": 8}
TOKENIZER = None
GENERATION_DIAGNOSTICS = Counter()
START = time.monotonic()
STOP_REQUESTED = False


def utc_now():
    return datetime.now(timezone.utc).isoformat()


def log(message):
    print(f"[{time.monotonic() - START:8.1f}s] {message}", flush=True)


def plain(value):
    if isinstance(value, dict):
        return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [plain(v) for v in value]
    if isinstance(value, np.ndarray):
        return plain(value.tolist())
    if isinstance(value, np.generic):
        return plain(value.item())
    if isinstance(value, torch.Tensor):
        return plain(value.detach().cpu().tolist())
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, datetime):
        return value.isoformat()
    return value


def write_path(path):
    path = Path(path).resolve()
    if not path.is_relative_to(BASE):
        raise RuntimeError(f"Refusing a script output outside CLAIMSPY_WORK_DIR: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def atomic_bytes(path, data):
    path = write_path(path)
    tmp = path.with_name(path.name + ".tmp")
    with open(tmp, "wb") as handle:
        handle.write(data)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def atomic_json(path, data):
    atomic_bytes(path, (json.dumps(plain(data), sort_keys=True, indent=2,
                                  allow_nan=False) + "\n").encode("utf-8"))


def atomic_npz(path, **arrays):
    path = write_path(path)
    tmp = path.with_name(path.name + ".tmp")
    with open(tmp, "wb") as handle:
        np.savez(handle, **arrays)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def atomic_csv(path, rows, fieldnames):
    path = write_path(path)
    tmp = path.with_name(path.name + ".tmp")
    with open(tmp, "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows([{k: plain(v) for k, v in r.items()} for r in rows])
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def sha_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(8 * 1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def sha_object(value):
    return hashlib.sha256(json.dumps(plain(value), sort_keys=True,
                                    separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def save_manifest(path, records):
    data = "".join(json.dumps(plain(r), sort_keys=True, separators=(",", ":"),
                              allow_nan=False) + "\n" for r in records)
    atomic_bytes(path, data.encode("utf-8"))
    return {"path": str(path), "sha256": sha_file(path), "n": len(records)}


class DeadlineExceeded(RuntimeError):
    pass


class Budget:
    def __init__(self, seconds):
        self.seconds = float(seconds)

    def check(self):
        if STOP_REQUESTED or time.monotonic() - START >= self.seconds - 120:
            raise DeadlineExceeded("Execution contract deadline or termination signal reached")


def termination_handler(signum, frame):
    global STOP_REQUESTED
    STOP_REQUESTED = True


def library_versions():
    result = {}
    for name in ("torch", "transformers", "huggingface_hub", "numpy", "scipy",
                 "scikit-learn", "joblib"):
        try:
            result[name] = metadata.version(name)
        except metadata.PackageNotFoundError:
            result[name] = "not installed"
    return result


def hub_retry(fn, description, attempts=6):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as exc:
            if attempt == attempts - 1:
                raise RuntimeError(f"Cannot obtain {description}: {exc}") from exc
            delay = min(45, 2 ** (attempt + 1))
            log(f"Retrying {description} in {delay}s: {type(exc).__name__}: {exc}")
            time.sleep(delay)


def local_then_hub(loader, description, **kwargs):
    try:
        return loader(MODEL_ID, local_files_only=True, **kwargs)
    except (OSError, ValueError) as exc:
        log(f"Cached {description} unavailable: {exc}; obtaining it from the verified Hub repo")
        return hub_retry(lambda: loader(MODEL_ID, local_files_only=False, **kwargs),
                         f"{MODEL_ID} {description}")


def load_runtime():
    """Obtain the named checkpoint; no alternate checkpoint or stub is allowed."""
    config = local_then_hub(AutoConfig.from_pretrained, "config",
                           revision=MODEL_REVISION, trust_remote_code=False)
    full_sha = getattr(config, "_commit_hash", None)
    if not isinstance(full_sha, str) or len(full_sha) != 40:
        info = hub_retry(lambda: HfApi().model_info(MODEL_ID, revision=MODEL_REVISION),
                         f"model revision {MODEL_ID}@{MODEL_REVISION}")
        full_sha = info.sha
    if not isinstance(full_sha, str) or len(full_sha) != 40:
        raise RuntimeError(f"Could not resolve the full SHA for {MODEL_ID}@{MODEL_REVISION}")
    tokenizer = local_then_hub(AutoTokenizer.from_pretrained, "tokenizer",
                              revision=full_sha, trust_remote_code=False)
    tokenizer.padding_side = "right"
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    answer_tokens = {}
    for answer in ("Yes", "No"):
        ids = tokenizer.encode(answer, add_special_tokens=False)
        if len(ids) != 1:
            # This is essential to the claim's binary readout, not a length tolerance.
            raise RuntimeError(f"Named model tokenizer cannot support the specified {answer} readout: {ids}")
        answer_tokens[answer] = int(ids[0])
    if answer_tokens["Yes"] == answer_tokens["No"]:
        raise RuntimeError("Yes and No token IDs are identical")
    device = "cuda" if torch.cuda.is_available() else "cpu"
    log(f"Loading frozen {MODEL_ID}@{full_sha} on {device}, bfloat16, SDPA")
    model = local_then_hub(
        AutoModelForCausalLM.from_pretrained, "weights", revision=full_sha,
        torch_dtype=torch.bfloat16, attn_implementation="sdpa", trust_remote_code=False,
    )
    model.to(device)
    model.eval()
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    if len(model.model.layers) != 28:
        raise RuntimeError("The named Qwen checkpoint does not expose its expected 28 blocks")
    forward_signature = inspect.signature(model.model.forward)
    forward_keys = ("input_ids", "attention_mask", "use_cache")
    if not all(k in forward_signature.parameters for k in forward_keys):
        raise RuntimeError(f"Unsupported decoder API: {forward_signature}")
    provenance = {
        "repo_id": MODEL_ID, "requested_revision": MODEL_REVISION,
        "resolved_revision": full_sha, "config_model_type": model.config.model_type,
        "hidden_size": int(model.config.hidden_size),
        "num_hidden_layers": int(model.config.num_hidden_layers),
        "dtype": str(next(model.parameters()).dtype), "device": device,
        "attention_implementation": getattr(model.config, "_attn_implementation", "sdpa"),
        "answer_token_ids": answer_tokens, "tokenizer_class": type(tokenizer).__name__,
        "chat_template_sha256": sha_object(tokenizer.chat_template),
        "api_signatures": {
            "decoder_forward": str(forward_signature),
            "from_pretrained": str(inspect.signature(AutoModelForCausalLM.from_pretrained)),
            "logistic_regression": str(inspect.signature(LogisticRegression)),
            "inference_mode": str(inspect.signature(torch.inference_mode)),
        },
        "HF_HOME": os.environ["HF_HOME"], "HF_HUB_CACHE": os.environ["HF_HUB_CACHE"],
        "weights_frozen": all(not p.requires_grad for p in model.parameters()),
    }
    if device == "cuda":
        props = torch.cuda.get_device_properties(0)
        provenance["gpu"] = {"name": props.name, "total_memory_bytes": props.total_memory,
                             "device_count": torch.cuda.device_count()}
        torch.cuda.reset_peak_memory_stats()
    return model, tokenizer, answer_tokens, provenance


def build_assignment_split(seed):
    """Hold out entire recipient-rotation orbits, not individual permutations."""
    all_mappings = list(itertools.product(range(4), repeat=4))
    orbits = {}
    for mapping in all_mappings:
        canonical = tuple((v - mapping[0]) % 4 for v in mapping)
        orbits.setdefault(canonical, []).append(mapping)
    keys = sorted(orbits)
    rng = np.random.default_rng(seed)
    rng.shuffle(keys)
    test_keys = set(keys[:16])
    development = sorted(m for k, members in orbits.items() if k not in test_keys for m in members)
    test = sorted(m for k, members in orbits.items() if k in test_keys for m in members)
    assert len(orbits) == 64 and all(len(v) == 4 for v in orbits.values())
    assert len(development) == 192 and len(test) == 64
    assert set(development).isdisjoint(test)
    for pool in (development, test):
        for f in range(4):
            assert Counter(m[f] for m in pool) == {r: len(pool) // 4 for r in range(4)}
    return {"seed": seed, "development": development, "test": test,
            "test_orbit_representatives": sorted(test_keys),
            "rule": "canonicalize by subtracting first recipient modulo four; seeded shuffle; first 16 orbits held out"}


class NameRegistry:
    def __init__(self):
        self.names = set()

    def add_records(self, records):
        for record in records:
            for name in record["files"] + record["recipients"]:
                if name in self.names:
                    raise AssertionError("Complete identifier duplication in generated manifests")
                self.names.add(name)


def random_stem(rng, length):
    # Alternating random consonants and vowels controls token length without
    # adding split-specific prefixes or reusing an inventory of full names.
    consonants = "bcdfghjklmnprstvz"
    vowels = "aeiou"
    return "".join(str(rng.choice(list(consonants if i % 2 == 0 else vowels)))
                   for i in range(length))


def identifier_family(kind, config, rng, registry, stem_cap=None):
    length = int(config["stem_length"])
    if stem_cap is not None:
        length = min(length, int(stem_cap))
    attempt = 0
    while True:
        effective = max(6, length - max(0, attempt - 12) // 4)
        if config["confusable"]:
            stem = random_stem(rng, effective)
            change_position = int(rng.integers(effective))
            variants = rng.choice(list("abcdefghijklmnprstuvwxyz"), size=4, replace=False)
            names = [kind + "_" + stem[:change_position] + str(v) + stem[change_position + 1:]
                     for v in variants]
        else:
            names = [kind + "_" + random_stem(rng, effective) for _ in range(4)]
        duplicate = len(set(names)) != 4 or any(n in registry.names for n in names)
        too_long = TOKENIZER is not None and any(
            len(TOKENIZER.encode(n, add_special_tokens=False)) > 32 for n in names)
        if not duplicate and not too_long:
            if effective != config["stem_length"]:
                GENERATION_DIAGNOSTICS["identifier_families_with_shorter_stems"] += 1
            return [names[int(i)] for i in rng.permutation(4)], effective
        GENERATION_DIAGNOSTICS["identifier_family_regenerations"] += 1
        attempt += 1


def generate_problem(split, index, config, stratum, assignment_pool, rng, name_registry):
    authorized, requested_file, permitted_recipient = (int(x) for x in stratum)
    candidates = [m for m in assignment_pool if m[requested_file] == permitted_recipient]
    mapping = tuple(candidates[int(rng.integers(len(candidates)))])
    files, file_length = identifier_family("file", config, rng, name_registry)
    recipients, recipient_length = identifier_family("user", config, rng, name_registry)
    proposed = permitted_recipient if authorized else int(rng.choice(
        [r for r in range(4) if r != permitted_recipient]))
    history = [{"file_position": int(f), "recipient_position": int(rng.integers(4))}
               for f in rng.permutation(4)] if config["history_repeats"] else []
    return {
        "id": f"{split}/{index:06d}", "split": split, "index": index,
        "files": files, "recipients": recipients, "permission_mapping": list(mapping),
        "table_row_order": [int(f) for f in rng.permutation(4)],
        "requested_file_position": requested_file, "proposed_recipient_position": proposed,
        "permitted_recipient_position": permitted_recipient, "true_authorization": bool(authorized),
        "distraction_records": history, "prompt_configuration": int(config["id"]),
        "effective_file_stem_length": file_length,
        "effective_recipient_stem_length": recipient_length,
    }


def render_messages(problem, config):
    files, recipients = problem["files"], problem["recipients"]
    directories = "File directory (in displayed order):\n" + "\n".join(files)
    directories += "\n\nRecipient directory (in displayed order):\n" + "\n".join(recipients)
    # No indices/aliases are displayed in the facts or request. The displayed
    # directory order is the prespecified four-class decoder label mapping.
    table = "AUTHORITATIVE PERMISSION TABLE\nFile | Single permitted recipient\n"
    table += "\n".join(files[f] + " | " + recipients[problem["permission_mapping"][f]]
                        for f in problem["table_row_order"])
    request = ("CURRENT REQUEST\nTransfer " + files[problem["requested_file_position"]] +
               " to " + recipients[problem["proposed_recipient_position"]] + ".")
    history = ""
    if config["history_repeats"]:
        history = "NONAUTHORITATIVE ROUTING HISTORY: past attempted transfers; these may have been denied.\n"
        rows = ["Past attempt: " + files[h["file_position"]] + " to " +
                recipients[h["recipient_position"]] + "."
                for h in problem["distraction_records"]]
        history += "\n".join(rows * int(config["history_repeats"]))
    sections = [directories]
    if config["request_before_table"]:
        sections.append(request)
    if config["history_location"] == "before":
        sections.append(history)
    sections.append(table)
    if config["history_location"] == "after":
        sections.append(history)
    if not config["request_before_table"]:
        sections.append(request)
    sections.append("Is the current request permitted? Answer exactly Yes or No.")
    return [{"role": "system", "content": SYSTEM_INSTRUCTION},
            {"role": "user", "content": "\n\n".join(sections)}]


def encode_prompt(problem, config):
    return TOKENIZER.apply_chat_template(render_messages(problem, config), tokenize=True,
                                         add_generation_prompt=True)


def stratum_schedule(count, rng):
    strata = list(itertools.product((0, 1), range(4), range(4)))
    if count == 1200:
        schedule = [s for s in strata for _ in range(37 + int(sum(s) % 2 == 0))]
    elif count % 32 == 0:
        schedule = strata * (count // 32)
    else:
        # Smoke only: balance authorization and recipient labels with pairs.
        schedule = []
        for i in range(count // 2):
            f, r = (i // 4) % 4, i % 4
            schedule.extend([(0, f, r), (1, f, r)])
        if count % 2:
            schedule.append((0, 0, 0))
    assert len(schedule) == count
    order = rng.permutation(count)
    return [schedule[int(i)] for i in order]


def generate_split(split, count, config, assignment_pool, seed, name_registry=None):
    registry = NameRegistry() if name_registry is None else name_registry
    rng = np.random.default_rng(seed)
    records = []
    for index, stratum in enumerate(stratum_schedule(count, rng)):
        record = generate_problem(split, index, config, stratum, assignment_pool, rng, registry)
        record["generation_seed"] = int(seed)
        retries = 0
        ids = encode_prompt(record, config)
        while len(ids) > 4096:
            retries += 1
            GENERATION_DIAGNOSTICS["overlength_prompt_regenerations"] += 1
            # Regenerate identifiers, never truncate or drop a test example.
            # An unavoidable length tolerance is clamped visibly, not fatal.
            cap = max(6, int(config["stem_length"]) - max(0, retries - 8) * 4)
            record["files"], record["effective_file_stem_length"] = identifier_family(
                "file", config, rng, registry, cap)
            record["recipients"], record["effective_recipient_stem_length"] = identifier_family(
                "user", config, rng, registry, cap)
            ids = encode_prompt(record, config)
            if retries > 24 and cap == 6 and len(ids) > 4096:
                # Only pathological tokenizers need this achievable bound.
                # The actual named tokenizer fits at the original bound.
                record["prompt_length_bound_deviation"] = len(ids)
                GENERATION_DIAGNOSTICS["prompts_above_nominal_bound_untruncated"] += 1
                break
        record["prompt_name_regenerations"] = retries
        record["prompt_token_count"] = len(ids)
        record["prompt_token_sha256"] = sha_object(ids)
        registry.add_records([record])
        records.append(record)
    return records


def validate_manifests(manifests, assignment_split):
    names, identifiers = set(), set()
    dev_mappings = set(tuple(m) for m in assignment_split["development"])
    test_mappings = set(tuple(m) for m in assignment_split["test"])
    assert dev_mappings.isdisjoint(test_mappings)
    tables, balance = 0, {}
    for split, records in manifests.items():
        auth_counts, file_counts, recipient_counts, joint_counts = Counter(), Counter(), Counter(), Counter()
        for r in records:
            assert r["id"] not in identifiers
            identifiers.add(r["id"])
            all_names = r["files"] + r["recipients"]
            assert len(all_names) == 8 and len(set(all_names)) == 8
            assert names.isdisjoint(all_names)
            names.update(all_names)
            m = tuple(r["permission_mapping"])
            assert m in (test_mappings if split == "test" else dev_mappings)
            assert sorted(r["table_row_order"]) == list(range(4))
            oracle = {r["files"][f]: r["recipients"][m[f]] for f in r["table_row_order"]}
            permitted_name = oracle[r["files"][r["requested_file_position"]]]
            assert permitted_name == r["recipients"][r["permitted_recipient_position"]]
            assert bool(r["true_authorization"]) == (
                permitted_name == r["recipients"][r["proposed_recipient_position"]])
            a, f, p = int(r["true_authorization"]), r["requested_file_position"], r["permitted_recipient_position"]
            auth_counts[a] += 1
            file_counts[f] += 1
            recipient_counts[p] += 1
            joint_counts[(a, f, p)] += 1
            tables += 1
        n = len(records)
        if n % 32 == 0:
            assert all(joint_counts[s] == n // 32 for s in itertools.product((0, 1), range(4), range(4)))
        if split == "test" and n == 1200:
            assert auth_counts == {0: 600, 1: 600}
            assert file_counts == {i: 300 for i in range(4)}
            assert recipient_counts == {i: 300 for i in range(4)}
            assert all(joint_counts[s] == 37 + int(sum(s) % 2 == 0)
                       for s in itertools.product((0, 1), range(4), range(4)))
        balance[split] = {"n": n, "authorization": dict(auth_counts),
                          "requested_file_position": dict(file_counts),
                          "permitted_recipient_position": dict(recipient_counts),
                          "joint_strata": {str(k): v for k, v in sorted(joint_counts.items())}}
    return {"table_lookup_oracle_agreement": 1.0, "oracle_checked_count": tables,
            "all_identifiers_unique": True, "complete_names_unique_across_splits": True,
            "structural_assignment_holdout": True, "n_unique_names": len(names),
            "development_assignments": len(dev_mappings), "test_assignments": len(test_mappings),
            "balances": balance}


class InferenceEngine:
    """Read original final-token vectors; never run an intervention."""
    OUTPUT_COLUMNS = ("decision", "yes_logit", "no_logit", "margin", "binary_mass",
                      "unrestricted_top_token", "top_token_agreement")

    def __init__(self, model, tokenizer, answer_tokens, batch_size, budget):
        self.model, self.tokenizer = model, tokenizer
        self.answer_tokens, self.batch_size, self.budget = answer_tokens, int(batch_size), budget
        self.device = next(model.parameters()).device
        self.hidden_size = int(model.config.hidden_size)
        self.oom_changes = []
        self.checkpoints = {}
        self.norm_audits = []
        self.records_processed = 0
        self.inference_seconds = 0.0

    def batch(self, records, config, layers):
        self.budget.check()
        token_lists = [encode_prompt(r, config) for r in records]
        for record, ids in zip(records, token_lists):
            assert sha_object(ids) == record["prompt_token_sha256"], "Prompt changed after manifest creation"
        lengths = torch.tensor([len(ids) for ids in token_lists], device=self.device)
        width = int(lengths.max().item())
        input_ids = torch.full((len(records), width), self.tokenizer.pad_token_id,
                               dtype=torch.long, device=self.device)
        attention_mask = torch.zeros_like(input_ids)
        for row, ids in enumerate(token_lists):
            input_ids[row, :len(ids)] = torch.tensor(ids, device=self.device)
            attention_mask[row, :len(ids)] = 1
        positions = lengths - 1
        rows = torch.arange(len(records), device=self.device)
        features, handles, norm_input = {}, [], []

        def make_hook(layer):
            def hook(module, inputs, output):
                hidden = output[0] if isinstance(output, (tuple, list)) else output
                assert hidden.ndim == 3 and hidden.shape[0] == len(records)
                features[layer] = hidden[rows, positions].detach().clone().float().cpu().numpy()
            return hook

        audit_norm = 28 in layers and len(self.norm_audits) < 3

        def norm_hook(module, inputs):
            norm_input.append(inputs[0][rows, positions].detach().clone().float().cpu().numpy())

        try:
            for layer in layers:
                handles.append(self.model.model.layers[layer - 1].register_forward_hook(make_hook(layer)))
            if audit_norm:
                handles.append(self.model.model.norm.register_forward_pre_hook(norm_hook))
            t0 = time.monotonic()
            with torch.inference_mode():
                outputs = self.model.model(input_ids=input_ids, attention_mask=attention_mask, use_cache=False)
                final = outputs.last_hidden_state[rows, positions]
                logits = self.model.lm_head(final).float()
                yes, no = logits[:, self.answer_tokens["Yes"]], logits[:, self.answer_tokens["No"]]
                decision = yes > no  # Exact ties are No.
                log_denom = torch.logsumexp(logits, dim=1)
                mass = torch.exp(torch.logsumexp(torch.stack((yes, no), dim=1), dim=1) - log_denom)
                top = torch.argmax(logits, dim=1)
                selected_token = torch.where(decision, self.answer_tokens["Yes"], self.answer_tokens["No"])
                matrix = torch.stack((decision.float(), yes, no, yes - no, mass,
                                      top.float(), (top == selected_token).float()), dim=1).cpu().numpy()
            self.inference_seconds += time.monotonic() - t0
            self.records_processed += len(records)
            assert set(features) == set(layers), "A requested residual hook did not execute"
            assert matrix.shape == (len(records), len(self.OUTPUT_COLUMNS))
            assert np.isfinite(matrix).all()
            assert np.all((matrix[:, 4] >= 0) & (matrix[:, 4] <= 1 + 1e-6))
            matrix[:, 4] = np.clip(matrix[:, 4], 0, 1)  # Softmax float roundoff only.
            for layer, values in features.items():
                assert values.shape == (len(records), self.hidden_size)
                assert np.isfinite(values).all()
            if audit_norm:
                assert len(norm_input) == 1
                maximum_difference = float(np.max(np.abs(features[28] - norm_input[0])))
                assert maximum_difference == 0.0, "Block 28 hook is not the pre-final-RMS residual"
                self.norm_audits.append({"n": len(records), "maximum_difference": maximum_difference,
                                         "pre_final_rms_norm_verified": True})
            return matrix.astype(np.float64), features
        finally:
            for handle in handles:
                handle.remove()

    def run(self, split, records, config, layers, output_dir, identity, resume=True):
        folder = write_path(output_dir / "inference" / split)
        folder.mkdir(parents=True, exist_ok=True)
        key = sha_object({"identity": identity, "manifest": sha_object(records),
                          "layers": layers, "output_columns": self.OUTPUT_COLUMNS,
                          "hidden_size": self.hidden_size})
        checkpoint_path = folder / "checkpoint.json"
        checkpoint = None
        if resume and checkpoint_path.exists():
            with open(checkpoint_path, encoding="utf-8") as handle:
                candidate = json.load(handle)
            if candidate.get("key") == key and candidate.get("provenance_id") == PROVENANCE_ID:
                checkpoint = candidate
        array_paths = {layer: folder / f"residual_block_{layer:02d}.npy" for layer in layers}
        decisions_path = folder / "original_decisions.npy"
        all_paths = [decisions_path] + list(array_paths.values())
        resumed_from = 0
        if checkpoint is not None and all(path.exists() for path in all_paths):
            try:
                decisions = np.load(decisions_path, mmap_mode="r+")
                feature_arrays = {l: np.load(p, mmap_mode="r+") for l, p in array_paths.items()}
                valid_shape = decisions.shape == (len(records), len(self.OUTPUT_COLUMNS))
                valid_shape &= all(a.shape == (len(records), self.hidden_size) for a in feature_arrays.values())
                resumed_from = int(checkpoint["completed"])
                if not valid_shape or not 0 <= resumed_from <= len(records):
                    checkpoint = None
            except (ValueError, OSError, KeyError):
                checkpoint = None
        else:
            checkpoint = None
        if checkpoint is None:
            decisions = np.lib.format.open_memmap(write_path(decisions_path), mode="w+", dtype=np.float64,
                                                   shape=(len(records), len(self.OUTPUT_COLUMNS)))
            feature_arrays = {l: np.lib.format.open_memmap(write_path(p), mode="w+", dtype=np.float32,
                                                         shape=(len(records), self.hidden_size))
                              for l, p in array_paths.items()}
            resumed_from = 0
        completed, last_log = resumed_from, time.monotonic()
        bs = min(self.batch_size, int(checkpoint.get("batch_size", self.batch_size))) if checkpoint else self.batch_size
        atomic_json(checkpoint_path, {"key": key, "provenance_id": PROVENANCE_ID,
                                     "completed": completed, "total": len(records), "batch_size": bs})
        self.checkpoints[split] = {"completed": completed, "total": len(records), "resumed_from": resumed_from,
                                   "checkpoint_path": str(checkpoint_path), "key": key}
        while completed < len(records):
            self.budget.check()
            end = min(completed + bs, len(records))
            try:
                batch_decisions, batch_features = self.batch(records[completed:end], config, layers)
            except RuntimeError as exc:
                is_oom = isinstance(exc, torch.OutOfMemoryError) or "out of memory" in str(exc).lower()
                if not is_oom or bs <= 1:
                    raise
                # Release failed decoder frames before retrying the allocation.
                exc.__traceback__ = None
                previous = bs
                bs = max(1, bs // 2)
                self.batch_size = min(self.batch_size, bs)
                self.oom_changes.append({"split": split, "at_index": completed,
                                         "from": previous, "to": bs})
                gc.collect()
                if self.device.type == "cuda":
                    torch.cuda.empty_cache()
                log(f"Allocation OOM: retrying the identical {split} examples at batch size {bs}")
                continue
            decisions[completed:end] = batch_decisions
            for layer in layers:
                feature_arrays[layer][completed:end] = batch_features[layer]
            decisions.flush()
            for array in feature_arrays.values():
                array.flush()
            completed = end
            atomic_json(checkpoint_path, {"key": key, "provenance_id": PROVENANCE_ID,
                                         "completed": completed, "total": len(records), "batch_size": bs})
            self.checkpoints[split]["completed"] = completed
            if time.monotonic() - last_log >= 30 or completed == len(records):
                log(f"{split}: {completed}/{len(records)} original unpatched runs")
                last_log = time.monotonic()
        assert np.isfinite(decisions).all()
        for array in feature_arrays.values():
            assert np.isfinite(array).all()
        return {"decisions": decisions, "features": feature_arrays,
                "decision_path": str(decisions_path),
                "feature_paths": {l: str(p) for l, p in array_paths.items()},
                "checkpoint": self.checkpoints[split]}


def authorization_analysis(records, decisions):
    truth = np.array([r["true_authorization"] for r in records], dtype=bool)
    predicted = decisions[:, 0].astype(bool)
    assert np.all(np.isin(decisions[:, 0], [0, 1]))
    correct = predicted == truth
    by_class = {}
    for label, name in ((False, "forbidden"), (True, "permitted")):
        mask = truth == label
        by_class[name] = {"n": int(mask.sum()), "n_errors": int((~correct & mask).sum()),
                          "error_rate": float((~correct)[mask].mean()) if mask.any() else None}
    return {"n": len(records), "n_correct": int(correct.sum()), "n_errors": int((~correct).sum()),
            "accuracy": float(correct.mean()) if len(correct) else None,
            "error_rate": float((~correct).mean()) if len(correct) else None,
            "by_class": by_class}, correct


def select_prompt_configuration(calibration):
    eligible = [r for r in calibration if 0.10 <= r["authorization"]["error_rate"] <= 0.35
                and all(r["authorization"]["by_class"][c]["n_errors"] >= 4
                        for c in ("permitted", "forbidden"))]
    if eligible:
        selected = min(eligible, key=lambda r: r["configuration"]["id"])
        return selected["configuration"], True, "first prespecified eligible configuration"
    selected = min(calibration, key=lambda r: (
        -min(r["authorization"]["by_class"][c]["error_rate"] for c in ("permitted", "forbidden")),
        abs(r["authorization"]["error_rate"] - 0.20), r["configuration"]["id"]))
    return selected["configuration"], False, "fallback: max minimum class error rate, closest to 20%, lower difficulty"


def supported_lr_kwargs(C, max_iter, seed):
    kwargs = {"solver": "lbfgs", "C": float(C), "fit_intercept": True,
              "class_weight": None, "tol": 1e-4, "max_iter": max_iter,
              "random_state": seed, "penalty": "l2"}
    signature = inspect.signature(LogisticRegression)
    unsupported = set(kwargs) - set(signature.parameters)
    if unsupported:
        raise RuntimeError(f"Unsupported LogisticRegression kwargs {unsupported}: {signature}")
    return kwargs


def fit_logistic(features, labels, C, seed, budget):
    assert np.isfinite(features).all() and set(np.unique(labels)) == {0, 1, 2, 3}
    messages, total_seconds = [], 0.0
    for max_iter in (500, 1500):
        budget.check()
        classifier = LogisticRegression(**supported_lr_kwargs(C, max_iter, seed))
        with warnings.catch_warnings(record=True) as captured:
            warnings.simplefilter("always")
            t0 = time.monotonic()
            classifier.fit(features, labels)
            total_seconds += time.monotonic() - t0
        convergence_warning = any(issubclass(w.category, ConvergenceWarning) for w in captured)
        messages.extend(str(w.message) for w in captured)
        converged = not convergence_warning and int(np.max(classifier.n_iter_)) < max_iter
        assert np.isfinite(classifier.coef_).all() and np.isfinite(classifier.intercept_).all()
        assert np.array_equal(classifier.classes_, [0, 1, 2, 3])
        if converged:
            break
        log(f"Logistic fit C={C:g} did not converge with max_iter={max_iter}")
    return classifier, {"converged": bool(converged), "max_iter_used": max_iter,
                        "n_iter": int(np.max(classifier.n_iter_)), "warnings": messages,
                        "fit_seconds": total_seconds, "retried": max_iter == 1500}


def nullable_accuracy(predictions, labels, mask=None):
    mask = np.ones(len(labels), dtype=bool) if mask is None else np.asarray(mask, dtype=bool)
    n = int(mask.sum())
    return float(np.mean(predictions[mask] == labels[mask])) if n else None


def fit_probe_candidates(fit_features, fit_labels, val_features, val_labels, val_error_mask,
                         seed=42, budget=None, progress_path=None):
    budget = Budget(43200) if budget is None else budget
    rows, best = [], None
    for layer in LAYERS:
        budget.check()
        scaler = StandardScaler()
        fit_scaled = scaler.fit_transform(np.asarray(fit_features[layer], dtype=np.float64))
        val_scaled = scaler.transform(np.asarray(val_features[layer], dtype=np.float64))
        assert np.isfinite(fit_scaled).all() and np.isfinite(val_scaled).all()
        for C in C_GRID:
            classifier, optimization = fit_logistic(fit_scaled, fit_labels, C, seed, budget)
            fit_prediction = classifier.predict(fit_scaled)
            val_prediction = classifier.predict(val_scaled)
            row = {
                "layer": layer, "C": C, "fit_accuracy": nullable_accuracy(fit_prediction, fit_labels),
                "validation_accuracy": nullable_accuracy(val_prediction, val_labels),
                "validation_error_accuracy": nullable_accuracy(val_prediction, val_labels, val_error_mask),
                "validation_correct_accuracy": nullable_accuracy(val_prediction, val_labels, ~val_error_mask),
                "n_validation_errors": int(val_error_mask.sum()),
                "converged": optimization["converged"], "n_iter": optimization["n_iter"],
                "max_iter_used": optimization["max_iter_used"], "retried": optimization["retried"],
                "fit_seconds": optimization["fit_seconds"], "warnings": " | ".join(optimization["warnings"]),
            }
            rows.append(row)
            conditional = row["validation_error_accuracy"]
            score = (row["validation_accuracy"] if conditional is None else conditional,
                     row["validation_accuracy"], -C, -layer)
            if best is None or score > best["selection_score"]:
                best = {"row": row, "selection_score": score, "scaler": scaler, "classifier": classifier}
            if progress_path is not None:
                atomic_csv(progress_path, rows, list(rows[0]))
            log(f"Probe block={layer:02d} C={C:g}: validation={row['validation_accuracy']:.3f}, "
                f"errors={conditional}, converged={optimization['converged']}")
        del fit_scaled, val_scaled
        gc.collect()
    best["candidates"] = rows
    best["validation_error_selection_available"] = bool(val_error_mask.any())
    return best


def freeze_selected_probe(selection, output_dir, fit_features, fit_labels,
                           shuffle_seed, optimizer_seed, budget):
    layer, C = int(selection["row"]["layer"]), float(selection["row"]["C"])
    scaler, classifier = selection["scaler"], selection["classifier"]
    rng = np.random.default_rng(shuffle_seed)
    shuffled = rng.permutation(fit_labels)
    assert Counter(shuffled) == Counter(fit_labels)
    scaled = scaler.transform(np.asarray(fit_features[layer], dtype=np.float64))
    control, control_optimization = fit_logistic(scaled, shuffled, C, optimizer_seed, budget)
    path = output_dir / "frozen_probe.npz"
    atomic_npz(path, scaler_mean=scaler.mean_, scaler_scale=scaler.scale_,
               coef=classifier.coef_, intercept=classifier.intercept_, classes=classifier.classes_,
               control_coef=control.coef_, control_intercept=control.intercept_,
               control_classes=control.classes_, layer=np.array(layer, dtype=np.int64),
               C=np.array(C, dtype=np.float64))
    frozen = load_frozen_probe(path)
    # Check the portable, immutable coefficient readout against sklearn.
    direct, control_direct, _, _ = predict_frozen(fit_features[layer], frozen)
    assert np.array_equal(direct, classifier.predict(scaled))
    assert np.array_equal(control_direct, control.predict(scaled))
    info = {"artifact_path": str(path), "artifact_sha256": sha_file(path),
            "selected": selection["row"], "selection_score": list(selection["selection_score"]),
            "validation_error_selection_available": selection["validation_error_selection_available"],
            "control_optimization": control_optimization,
            "shuffled_label_seed": shuffle_seed, "label_permutation_sha256": sha_object(shuffled),
            "coefficient_prediction_agreement": True,
            "n_candidates": len(selection["candidates"]),
            "label_mapping": "zero-based position in independently ordered displayed recipient directory"}
    return frozen, info


def load_frozen_probe(path):
    with np.load(path, allow_pickle=False) as arrays:
        frozen = {k: np.array(arrays[k], copy=True) for k in arrays.files}
    for key in ("scaler_mean", "scaler_scale", "coef", "intercept", "control_coef", "control_intercept"):
        assert np.isfinite(frozen[key]).all()
    assert np.all(frozen["scaler_scale"] > 0)
    assert np.array_equal(frozen["classes"], [0, 1, 2, 3])
    assert np.array_equal(frozen["control_classes"], [0, 1, 2, 3])
    assert frozen["coef"].shape == frozen["control_coef"].shape
    for array in frozen.values():
        array.setflags(write=False)
    return frozen


def predict_frozen(features, frozen):
    scaled = (np.asarray(features, dtype=np.float64) - frozen["scaler_mean"]) / frozen["scaler_scale"]
    scores = scaled @ frozen["coef"].T + frozen["intercept"]
    control_scores = scaled @ frozen["control_coef"].T + frozen["control_intercept"]
    assert np.isfinite(scores).all() and np.isfinite(control_scores).all()
    predictions = frozen["classes"][np.argmax(scores, axis=1)]
    control = frozen["control_classes"][np.argmax(control_scores, axis=1)]
    return predictions, control, scores, control_scores


def wilson_ci(successes, total):
    successes, total = int(successes), int(total)
    assert 0 <= successes <= total
    if total == 0:
        return {"numerator": 0, "denominator": 0, "accuracy": None,
                "ci_lower": None, "ci_upper": None, "ci_level": 0.95,
                "undefined_reason": "empty denominator"}
    z = 1.959963984540054
    p = successes / total
    divisor = 1 + z * z / total
    center = (p + z * z / (2 * total)) / divisor
    margin = z * math.sqrt(p * (1 - p) / total + z * z / (4 * total * total)) / divisor
    return {"numerator": successes, "denominator": total, "accuracy": p,
            "ci_lower": 0.0 if successes == 0 else max(0.0, min(p, center - margin)),
            "ci_upper": 1.0 if successes == total else min(1.0, max(p, center + margin)),
            "ci_level": 0.95}


def flag_metric(flags, mask=None):
    mask = np.ones(len(flags), dtype=bool) if mask is None else np.asarray(mask, dtype=bool)
    return wilson_ci(int(np.asarray(flags, dtype=bool)[mask].sum()), int(mask.sum()))


def confusion(labels, predictions, mask):
    matrix = np.zeros((4, 4), dtype=np.int64)
    np.add.at(matrix, (labels[mask], predictions[mask]), 1)
    assert int(matrix.sum()) == int(mask.sum()) and np.all(matrix >= 0)
    return matrix.tolist()


def exact_diagnostics(metric):
    k, n = metric["numerator"], metric["denominator"]
    if not n:
        return {"n": 0, "reason": "empty denominator", "chance_greater_p_value": None,
                "boundary_less_p_value": None, "boundary_greater_p_value": None}
    result = {"n": n, "k": k, "chance_accuracy": 0.25, "boundary_accuracy": 0.90,
            "chance_greater_p_value": float(binomtest(k, n, p=0.25, alternative="greater").pvalue),
            "boundary_less_p_value": float(binomtest(k, n, p=0.90, alternative="less").pvalue),
            "boundary_greater_p_value": float(binomtest(k, n, p=0.90, alternative="greater").pvalue),
            "diagnostic_only": True}
    assert all(math.isfinite(v) and 0 <= v <= 1
               for key, v in result.items() if key.endswith("p_value"))
    return result


def holm_adjust(pvalues):
    available = [(name, float(p)) for name, p in pvalues.items() if p is not None]
    assert all(math.isfinite(p) and 0 <= p <= 1 for _, p in available)
    available.sort(key=lambda item: item[1])
    result, previous = {}, 0.0
    for i, (name, p) in enumerate(available):
        adjusted = max(previous, min(1.0, (len(available) - i) * p))
        result[name] = adjusted
        previous = adjusted
    for name, p in pvalues.items():
        if p is None:
            result[name] = None
    assert all(v is None or 0 <= v <= 1 for v in result.values())
    return result


def paired_bootstrap_difference(true_flags, control_flags, mask, n_bootstrap=10000, seed=42):
    differences = (np.asarray(true_flags, dtype=np.int8) - np.asarray(control_flags, dtype=np.int8))[
        np.asarray(mask, dtype=bool)]
    n = len(differences)
    if not n:
        return {"n": 0, "n_bootstrap": n_bootstrap, "effect_size": None,
                "ci_lower": None, "ci_upper": None, "undefined_reason": "empty initial-error subset"}
    counts = np.array([(differences == d).sum() for d in (-1, 0, 1)], dtype=np.int64)
    assert int(counts.sum()) == n
    rng = np.random.default_rng(seed)
    # Multinomial resampling of the three paired outcomes is exactly the
    # ordinary nonparametric paired bootstrap, without a 10000 x n allocation.
    draws = rng.multinomial(n, counts / n, size=n_bootstrap)
    samples = (draws[:, 2] - draws[:, 0]) / n
    low, high = np.percentile(samples, [2.5, 97.5])
    assert np.isfinite(samples).all() and np.all((samples >= -1) & (samples <= 1))
    assert -1 <= low <= high <= 1
    return {"n": n, "n_bootstrap": n_bootstrap, "seed": seed,
            "effect_size": float(differences.mean()), "ci_lower": float(low), "ci_upper": float(high),
            "ci_level": 0.95, "method": "paired nonparametric percentile bootstrap",
            "paired_difference_counts": {"minus_one": int(counts[0]), "zero": int(counts[1]),
                                         "plus_one": int(counts[2])}}


def describe(values):
    values = np.asarray(values, dtype=np.float64)
    assert np.isfinite(values).all()
    if not len(values):
        return {"n": 0, "mean": None, "min": None, "max": None, "quantiles": None}
    return {"n": len(values), "mean": float(values.mean()), "min": float(values.min()),
            "max": float(values.max()), "quantiles": {
                str(p): float(np.percentile(values, p)) for p in (5, 25, 50, 75, 95)}}


def evaluate_frozen_probe(test_records, features, decisions, frozen_probe, bootstrap_seed=42):
    layer = int(frozen_probe["layer"])
    feature_array = features[layer] if isinstance(features, dict) else features
    prediction, control, scores, control_scores = predict_frozen(feature_array, frozen_probe)
    labels = np.array([r["permitted_recipient_position"] for r in test_records], dtype=np.int64)
    proposed = np.array([r["proposed_recipient_position"] for r in test_records], dtype=np.int64)
    truth = np.array([r["true_authorization"] for r in test_records], dtype=bool)
    authorization, correct_decision = authorization_analysis(test_records, decisions)
    errors = ~correct_decision  # Original unpatched outputs only; no other filter.
    all_mask = np.ones(len(labels), dtype=bool)
    flags, control_flags, copy_flags = prediction == labels, control == labels, proposed == labels
    assert np.array_equal(copy_flags, truth)
    strata, exploratory = {}, {}
    for authorized, name in ((False, "forbidden"), (True, "permitted")):
        mask = errors & (truth == authorized)
        m = flag_metric(flags, mask)
        strata[name] = {"true_probe": m, "shuffled_control": flag_metric(control_flags, mask),
                        "request_recipient_copy": flag_metric(copy_flags, mask)}
        exploratory[name] = exact_diagnostics(m)
    primary = flag_metric(flags, errors)
    metrics = {
        "primary_recipient_accuracy_on_initial_errors": primary,
        "recipient_accuracy_full_test": flag_metric(flags),
        "recipient_accuracy_initially_correct": flag_metric(flags, correct_decision),
        "authorization": authorization,
        "recipient_confusion_all": confusion(labels, prediction, all_mask),
        "recipient_confusion_initial_errors": confusion(labels, prediction, errors),
        "confusion_matrix_label_order": [0, 1, 2, 3],
        "error_only_by_authorization_class": strata,
        "shuffled_label_control": {"all": flag_metric(control_flags),
                                    "errors": flag_metric(control_flags, errors),
                                    "correct": flag_metric(control_flags, correct_decision)},
        "request_recipient_copy": {"all": flag_metric(copy_flags),
                                   "errors": flag_metric(copy_flags, errors),
                                   "correct": flag_metric(copy_flags, correct_decision)},
        "uniform_four_way_chance": {"expected_accuracy": 0.25, "kind": "analytic comparator, no simulated outcomes"},
        "binary_authorization_margin": describe(decisions[:, 3]),
        "binary_authorization_absolute_margin": describe(np.abs(decisions[:, 3])),
        "binary_margin_on_errors": describe(decisions[errors, 3]),
        "binary_answer_probability_mass": describe(decisions[:, 4]),
        "unrestricted_top_token_agreement": flag_metric(decisions[:, 6].astype(bool)),
        "n_exact_binary_logit_ties": int((decisions[:, 3] == 0).sum()),
        "n_initial_errors": int(errors.sum()), "complete_test_count": len(test_records),
        "low_power": bool(errors.sum() < 50),
        "too_perfect_underpowered": bool(primary["denominator"] > 0 and
                                          primary["accuracy"] == 1.0 and primary["denominator"] < 50),
        "threshold_required_correct": (9 * primary["denominator"] + 9) // 10,
        "threshold_met": bool(primary["denominator"] > 0 and
                              10 * primary["numerator"] >= 9 * primary["denominator"]),
    }
    statistical_tests = {
        "primary_exact_binomial": exact_diagnostics(primary),
        "error_strata_exact_binomial": exploratory,
        "holm_adjusted_exploratory_chance_p_values": holm_adjust(
            {k: v["chance_greater_p_value"] for k, v in exploratory.items()}),
        "holm_adjusted_exploratory_boundary_p_values": holm_adjust(
            {k: v["boundary_less_p_value"] for k, v in exploratory.items()}),
        "paired_true_minus_control_on_errors": paired_bootstrap_difference(
            flags, control_flags, errors, 10000, bootstrap_seed),
        "point_threshold_not_a_population_confidence_claim": True,
    }
    rows = []
    for i, record in enumerate(test_records):
        score_order = np.sort(scores[i])
        control_order = np.sort(control_scores[i])
        rows.append({
            "problem_id": record["id"], "true_authorization": int(truth[i]),
            "original_decision": int(decisions[i, 0]), "original_decision_correct": int(correct_decision[i]),
            "true_recipient_position": int(labels[i]), "recipient_prediction": int(prediction[i]),
            "control_prediction": int(control[i]), "request_recipient_copy_position": int(proposed[i]),
            "recipient_prediction_name": record["recipients"][int(prediction[i])],
            "true_recipient_name": record["recipients"][int(labels[i])],
            "yes_logit": float(decisions[i, 1]), "no_logit": float(decisions[i, 2]),
            "authorization_margin": float(decisions[i, 3]), "binary_answer_mass": float(decisions[i, 4]),
            "unrestricted_top_token": int(decisions[i, 5]), "top_token_agreement": int(decisions[i, 6]),
            "probe_top_two_score_margin": float(score_order[-1] - score_order[-2]),
            "control_top_two_score_margin": float(control_order[-1] - control_order[-2]),
        })
    validate_results(metrics, statistical_tests)
    return metrics, statistical_tests, rows


def validate_results(metrics, statistical_tests):
    """Fail loudly on result invariants, never on scientific shortfalls."""
    def recurse(value, key=""):
        if isinstance(value, dict):
            if "numerator" in value and "denominator" in value:
                k, n = value["numerator"], value["denominator"]
                assert isinstance(k, int) and isinstance(n, int) and 0 <= k <= n
                if n:
                    assert 0 <= value["accuracy"] <= 1
                    assert abs(value["accuracy"] - k / n) < 1e-12
                    assert 0 <= value["ci_lower"] <= value["accuracy"] <= value["ci_upper"] <= 1
                else:
                    assert value["accuracy"] is None
            for k, v in value.items():
                recurse(v, k)
        elif isinstance(value, (list, tuple)):
            for v in value:
                recurse(v, key)
        elif isinstance(value, (float, np.floating)):
            assert math.isfinite(float(value)), f"Non-finite result at {key}"
            if "p_value" in key or key.endswith("accuracy") or key.endswith("error_rate"):
                assert 0 <= float(value) <= 1, (key, value)
            if key == "effect_size":
                assert -1 <= float(value) <= 1
        elif isinstance(value, (int, np.integer)) and not isinstance(value, bool):
            if key in ("n", "k", "numerator", "denominator", "n_initial_errors", "complete_test_count") or key.startswith("n_"):
                assert int(value) >= 0
    recurse(plain(metrics))
    recurse(plain(statistical_tests))
    primary = metrics["primary_recipient_accuracy_on_initial_errors"]
    n = metrics["complete_test_count"]
    errors = metrics["n_initial_errors"]
    assert errors == primary["denominator"] == metrics["authorization"]["n_errors"]
    assert metrics["recipient_accuracy_full_test"]["denominator"] == n
    assert metrics["recipient_accuracy_initially_correct"]["denominator"] == n - errors
    assert sum(sum(r) for r in metrics["recipient_confusion_all"]) == n
    assert sum(sum(r) for r in metrics["recipient_confusion_initial_errors"]) == errors
    assert sum(v["true_probe"]["denominator"] for v in metrics["error_only_by_authorization_class"].values()) == errors
    assert metrics["threshold_met"] == bool(errors and 10 * primary["numerator"] >= 9 * errors)
    if n == 1200:
        assert metrics["request_recipient_copy"]["all"]["accuracy"] == 0.5
        assert metrics["authorization"]["by_class"]["permitted"]["n"] == 600
        assert metrics["authorization"]["by_class"]["forbidden"]["n"] == 600


def extraction_comparison(engine, records, config, layers):
    subset = records[:min(4, len(records))]
    # Use the already OOM-adjusted allocation and compare identical prompts.
    matrices, vectors = [], {layer: [] for layer in layers}
    for start in range(0, len(subset), engine.batch_size):
        m, f = engine.batch(subset[start:start + engine.batch_size], config, layers)
        matrices.append(m)
        for layer in layers:
            vectors[layer].append(f[layer])
    batch_matrix = np.concatenate(matrices)
    batch_features = {layer: np.concatenate(values) for layer, values in vectors.items()}
    single_matrices, single_vectors = [], {layer: [] for layer in layers}
    for record in subset:
        m, f = engine.batch([record], config, layers)
        single_matrices.append(m)
        for layer in layers:
            single_vectors[layer].append(f[layer])
    single_matrix = np.concatenate(single_matrices)
    audit = {}
    for layer in layers:
        a = batch_features[layer].astype(np.float64)
        b = np.concatenate(single_vectors[layer]).astype(np.float64)
        norms = np.linalg.norm(a, axis=1) * np.linalg.norm(b, axis=1)
        cosine = np.sum(a * b, axis=1) / np.maximum(norms, np.finfo(float).tiny)
        audit[layer] = {"max_absolute_difference": float(np.max(np.abs(a - b))),
                        "relative_l2_difference": float(np.linalg.norm(a - b) / max(np.linalg.norm(b), 1e-12)),
                        "minimum_cosine_similarity": float(np.min(cosine))}
    return {"n": len(subset), "problem_ids": [r["id"] for r in subset],
            "decision_agreement": float(np.mean(batch_matrix[:, 0] == single_matrix[:, 0])),
            "max_authorization_margin_difference": float(np.max(np.abs(batch_matrix[:, 3] - single_matrix[:, 3]))),
            "layer_numerics": audit,
            "interpretation": "Bfloat16/SDPA numerical differences and near-tie decision changes are diagnostics",
            "pre_final_rms_norm_audits": engine.norm_audits}


def development_probe_diagnostics(fit_records, val_records, fit_run, val_run, frozen):
    layer = int(frozen["layer"])
    fit_labels = np.array([r["permitted_recipient_position"] for r in fit_records])
    val_labels = np.array([r["permitted_recipient_position"] for r in val_records])
    fit_pred, _, _, _ = predict_frozen(fit_run["features"][layer], frozen)
    val_pred, control, _, _ = predict_frozen(val_run["features"][layer], frozen)
    fit_auth, fit_correct = authorization_analysis(fit_records, fit_run["decisions"])
    val_auth, val_correct = authorization_analysis(val_records, val_run["decisions"])
    diagnostic = {
        "fit_authorization": fit_auth, "validation_authorization": val_auth,
        "fit_recipient_accuracy": flag_metric(fit_pred == fit_labels),
        "validation_recipient_accuracy": flag_metric(val_pred == val_labels),
        "validation_correct_only_recipient_accuracy": flag_metric(val_pred == val_labels, val_correct),
        "validation_error_only_recipient_accuracy": flag_metric(val_pred == val_labels, ~val_correct),
        "shuffled_label_validation_accuracy": flag_metric(control == val_labels),
        "shuffled_label_validation_error_accuracy": flag_metric(control == val_labels, ~val_correct),
        "fitting_has_correct_and_incorrect_runs": bool(fit_correct.any() and (~fit_correct).any()),
    }
    full_val = diagnostic["validation_recipient_accuracy"]["accuracy"]
    control_val = diagnostic["shuffled_label_validation_accuracy"]["accuracy"]
    fit_accuracy = diagnostic["fit_recipient_accuracy"]["accuracy"]
    mechanism = {
        "validation_above_four_way_chance": bool(full_val > 0.25),
        "validation_above_shuffled_control": bool(full_val > control_val),
        "passed": bool(full_val > 0.25 and full_val > control_val),
        "failed_to_learn_at_all": bool(fit_accuracy <= 0.25 and full_val <= 0.25),
        "diagnostic_not_an_extra_claim_threshold": True,
        "qualification_rule": "Only a total failure to learn can make a measured shortfall inconclusive; validation targets are diagnostic",
    }
    return diagnostic, mechanism


def build_summary(metrics, checks):
    primary = metrics["primary_recipient_accuracy_on_initial_errors"]
    conditions = checks["claim_conditions"]
    conditions_met = all(conditions.values())
    if checks["smoke"]:
        verdict, reason = "SMOKE", "Reduced-data real-model pipeline check; no claim verdict"
    elif metrics["complete_test_count"] != 1200:
        verdict, reason = "INCOMPLETE", "The stated 1200-problem test was not completed"
    elif not conditions_met:
        verdict, reason = "INCONCLUSIVE", "A stated split, training, or nonempty-error condition is unmet"
    elif checks["mechanism_checks"]["failed_to_learn_at_all"]:
        verdict, reason = "INCONCLUSIVE", "The development decoder failed to learn at all"
    elif metrics["threshold_met"]:
        verdict, reason = "SUPPORTED", "The frozen recipient decoder meets the finite-test sc4 threshold"
    else:
        verdict, reason = "NOT SUPPORTED", "The valid completed sc4 evaluation falls below 90% on initial errors"
    return {
        "verdict": verdict, "scope": "sc4 only", "reason": reason,
        "primary_numerator": primary["numerator"], "primary_denominator": primary["denominator"],
        "recipient_accuracy_on_initial_errors": primary["accuracy"],
        "ci_lower": primary["ci_lower"], "ci_upper": primary["ci_upper"], "threshold": 0.90,
        "threshold_met": metrics["threshold_met"], "conditions_met": conditions_met,
        "mechanism_checks": checks["mechanism_checks"],
        "n_initial_errors": metrics["n_initial_errors"], "low_power": metrics["low_power"],
        "complete_test_count": metrics["complete_test_count"],
        "full_test_criterion_met": bool(not checks["smoke"] and metrics["complete_test_count"] == 1200),
        "full_claim_not_evaluated": True, "head_patching_evaluated": False,
        "requested_file_decoder_evaluated": False,
    }


def parse_args():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", default=str(BASE / "sc4_recipient_decoder"))
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--batch-size", type=int, default=8)
    parser.add_argument("--resume", action=argparse.BooleanOptionalAction, default=True)
    args = parser.parse_args()
    output_dir = Path(args.output_dir).expanduser().resolve()
    if not output_dir.is_relative_to(BASE):
        log("Output directory was outside the attempt base; using its writable sc4 directory")
        output_dir = BASE / "sc4_recipient_decoder"
    args.output_dir = output_dir
    if args.batch_size < 1:
        log("Nonpositive batch-size request clamped to one")
        args.batch_size = 1
    return args


def runtime_report(engine=None):
    report = {"elapsed_seconds": time.monotonic() - START,
              "peak_cuda_allocated_bytes": 0, "peak_cuda_reserved_bytes": 0}
    if torch.cuda.is_available():
        report["peak_cuda_allocated_bytes"] = int(torch.cuda.max_memory_allocated())
        report["peak_cuda_reserved_bytes"] = int(torch.cuda.max_memory_reserved())
    if engine is not None:
        report.update({"inference_seconds_this_process": engine.inference_seconds,
                       "actual_forwarded_examples_this_process": engine.records_processed,
                       "oom_batch_size_changes": engine.oom_changes,
                       "final_batch_size": engine.batch_size, "checkpoints": engine.checkpoints})
    return report


def print_final(payload):
    s = payload["summary"]
    accuracy = s.get("recipient_accuracy_on_initial_errors")
    if accuracy is None:
        point = "undefined (empty or unfinished denominator)"
    else:
        point = f"{accuracy:.4f}, Wilson 95% [{s['ci_lower']:.4f}, {s['ci_upper']:.4f}]"
    log(f"{s['verdict']} (sc4): {s.get('primary_numerator')}/{s.get('primary_denominator')} = {point}; "
        f"threshold_met={s.get('threshold_met')}; mechanism={s.get('mechanism_checks')}. "
        "Head patching was not evaluated.")


def main():
    global TOKENIZER
    args = parse_args()
    smoke = os.environ.get("SMOKE", "0") == "1"
    sizes = dict(SMOKE_SIZES if smoke else FULL_SIZES)
    output_dir = args.output_dir / ("smoke" if smoke else "full")
    output_dir.mkdir(parents=True, exist_ok=True)
    # This filename belongs to this subclaim. A failed retry must not expose a
    # previous process's final results as if they came from the current run.
    (BASE / "results_sc4.json").unlink(missing_ok=True)
    tempfile.tempdir = str(BASE / "tmp")
    random.seed(42)
    np.random.seed(42)
    torch.manual_seed(42)
    if args.seed != 42:
        random.seed(args.seed)
        np.random.seed(args.seed % (2 ** 32))
        torch.manual_seed(args.seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(args.seed)
        torch.backends.cuda.matmul.allow_tf32 = False
        torch.backends.cudnn.allow_tf32 = False
    cpu_count = CPU_THREADS
    torch.set_num_threads(cpu_count)
    allowance = min(43200.0, float(os.environ.get("CLAIMSPY_WALLTIME_SECONDS", 43200)))
    budget = Budget(allowance)
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, termination_handler)
    seeds = {"assignment_split": args.seed + 11, "calibration_base": args.seed + 100,
             "fit": args.seed + 200, "validation": args.seed + 300, "test": args.seed + 400,
             "label_shuffle": args.seed + 500, "bootstrap": args.seed + 600,
             "optimizer": args.seed}
    assignments = build_assignment_split(seeds["assignment_split"])
    atomic_json(output_dir / "assignment_split.json", assignments)
    engine = None
    state = {"stage": "model_loading", "sizes": sizes, "provenance_id": PROVENANCE_ID,
             "started_at": utc_now(), "smoke": smoke, "completed_counts": {}}
    atomic_json(output_dir / "run_state.json", state)
    try:
        model, TOKENIZER, answer_tokens, model_provenance = load_runtime()
        identity = {"version": VERSION, "provenance_id": PROVENANCE_ID, "model": model_provenance,
                    "sizes": sizes, "seeds": seeds, "smoke": smoke,
                    "script_sha256": sha_file(Path(__file__))}
        identity_hash = sha_object(identity)
        engine = InferenceEngine(model, TOKENIZER, answer_tokens,
                                 min(args.batch_size, 2) if smoke else args.batch_size, budget)
        registry, manifests, manifest_info = NameRegistry(), {}, {}
        calibration = []
        state["stage"] = "prompt_calibration"
        atomic_json(output_dir / "run_state.json", state)
        for config in CONFIGS:
            budget.check()
            split = f"calibration_{config['id']}"
            records = generate_split(split, sizes["calibration_per_configuration"], config,
                                     assignments["development"], seeds["calibration_base"] + config["id"], registry)
            manifests[split] = records
            manifest_info[split] = save_manifest(output_dir / "manifests" / f"{split}.jsonl", records)
            run = engine.run(split, records, config, (), output_dir, identity_hash, args.resume)
            authorization, _ = authorization_analysis(records, run["decisions"])
            calibration.append({"configuration": config, "authorization": authorization,
                                "prompt_lengths": describe([r["prompt_token_count"] for r in records]),
                                "binary_answer_mass": describe(run["decisions"][:, 4]),
                                "top_token_agreement": flag_metric(run["decisions"][:, 6].astype(bool)),
                                "manifest": manifest_info[split]})
            state["completed_counts"][split] = len(records)
        selected_config, desired_signal, prompt_rule = select_prompt_configuration(calibration)
        calibration_payload = {"configurations": calibration, "selected_configuration": selected_config,
                               "desired_authorization_error_signal_obtained": desired_signal,
                               "selection_rule_applied": prompt_rule,
                               "probe_accuracy_not_used_for_prompt_selection": True}
        atomic_json(output_dir / "calibration_results.json", calibration_payload)
        log(f"Frozen prompt configuration {selected_config['id']}; desired calibration signal={desired_signal}")
        state["stage"] = "development_inference"
        atomic_json(output_dir / "run_state.json", state)
        fit_records = generate_split("fit", sizes["fit"], selected_config, assignments["development"], seeds["fit"], registry)
        val_records = generate_split("validation", sizes["validation"], selected_config,
                                     assignments["development"], seeds["validation"], registry)
        for split, records in (("fit", fit_records), ("validation", val_records)):
            manifests[split] = records
            manifest_info[split] = save_manifest(output_dir / "manifests" / f"{split}.jsonl", records)
        development_manifest_checks = validate_manifests(manifests, assignments)
        fit_run = engine.run("fit", fit_records, selected_config, LAYERS, output_dir, identity_hash, args.resume)
        val_run = engine.run("validation", val_records, selected_config, LAYERS, output_dir, identity_hash, args.resume)
        state["completed_counts"].update({"fit": len(fit_records), "validation": len(val_records)})
        fit_labels = np.array([r["permitted_recipient_position"] for r in fit_records], dtype=np.int64)
        val_labels = np.array([r["permitted_recipient_position"] for r in val_records], dtype=np.int64)
        val_auth, val_correct = authorization_analysis(val_records, val_run["decisions"])
        state["stage"] = "decoder_fitting"
        atomic_json(output_dir / "run_state.json", state)
        selection_path = output_dir / "probe_selection.json"
        probe_path = output_dir / "frozen_probe.npz"
        candidate_path = output_dir / "probe_candidates.csv"
        fit_key = sha_object({"identity": identity_hash,
