                              "C_grid": C_GRID, "layers": LAYERS,
                              "label_shuffle_seed": seeds["label_shuffle"]})
        probe_info = None
        if args.resume and selection_path.exists() and probe_path.exists() and candidate_path.exists():
            with open(selection_path, encoding="utf-8") as handle:
                cached = json.load(handle)
            if (cached.get("fit_key") == fit_key and cached.get("provenance_id") == PROVENANCE_ID
