            frozen, probe_info = freeze_selected_probe(selection, output_dir, fit_run["features"], fit_labels,
                                                      seeds["label_shuffle"], seeds["optimizer"], budget)
            probe_info.update({"fit_key": fit_key, "provenance_id": PROVENANCE_ID,
                               "candidate_csv_sha256": sha_file(candidate_path)})
            atomic_json(selection_path, probe_info)
            del selection
        assert probe_info["n_candidates"] == len(LAYERS) * len(C_GRID)
        development, mechanism = development_probe_diagnostics(fit_records, val_records, fit_run, val_run, frozen)
        extraction = extraction_comparison(engine, val_records, selected_config, LAYERS)
        log(f"Selected decoder block={int(frozen['layer'])}, C={float(frozen['C']):g}; mechanism={mechanism}")
        protocol = {
