        }
        validate_results(metrics, statistical_tests)
        assert summary["primary_denominator"] == metrics["n_initial_errors"]
        assert sha_file(frozen_path) == frozen_protocol_sha
        json.dumps(plain(payload), allow_nan=False)  # Validate the whole serialization boundary.
        atomic_json(BASE / "results_sc4.json", payload)
        assert (BASE / "results_sc4.json").exists()
        state["stage"] = "complete"
        state["finished_at"] = utc_now()
        atomic_json(output_dir / "run_state.json", state)
        print_final(payload)
        return 0
    except DeadlineExceeded as exc:
        state["stage_at_deadline"] = state["stage"]
        state["stage"] = "incomplete"
        completed_test = int(engine.checkpoints.get("test", {}).get("completed", 0)) if engine else 0
        summary = {"verdict": "INCOMPLETE", "scope": "sc4 only", "reason": str(exc),
                   "threshold_met": None, "conditions_met": False, "n_initial_errors": None,
                   "complete_test_count": completed_test, "required_test_count": 1200,
