            "checks": {"partial_run_not_a_threshold_measurement": True},
            "runtime": runtime_report(engine), "state": state})
        atomic_json(output_dir / "run_state.json", state)
        log(f"INCOMPLETE: {exc}; retained same-protocol atomic checkpoints for a retry")
        return 2
    except Exception as exc:
        # Never replace a missing model or a broken implementation with outcomes.
        atomic_json(output_dir / "failure_diagnostic.json", {
            "provenance_id": PROVENANCE_ID, "stage": state["stage"],
            "exception": type(exc).__name__, "reason": str(exc),
            "runtime": runtime_report(engine), "completed_counts": state["completed_counts"],
            "no_scientific_results_generated_by_this_failure": True})
        log(f"FAILED in {state['stage']}: {type(exc).__name__}: {exc}")
        raise


if __name__ == "__main__":
    raise SystemExit(main())

