Run: python experiment_sc5.py. No file transfer, external tool execution, model
training, human annotation, or previous experiment artifacts are involved.
SMOKE=1 reduces only the experiment sizes, using the released model and the
same inference, hook, selection, controls, analysis, and persistence code.
The four linear-decoder subclaims are deliberately outside this commission.
"""
import os
import sys
from pathlib import Path

sys.dont_write_bytecode = True
BASE = Path(os.environ.get("CLAIMSPY_WORK_DIR", "/vast/projects/ccb/lab/ClaimSpyV2-jludan/sandbox/515")).expanduser().resolve()
